/**
 * Constructor.
 *
 * @param fontDictionary
 * 		the corresponding dictionary
 * @throws IOException
 * 		it something went wrong
 */
public (COSDictionary fontDictionary) throws IOException // PATH: Test should invoke the next PDSimpleFont.readEncoding(...) [step in execution path]
{
    this(fontDictionary);
    boolean fontIsDamaged = false;
    CFFType1Font cffEmbedded = null;
    PDFontDescriptor fd = getFontDescriptor();
    if (fd != null) {
        PDStream ff3Stream = fd.getFontFile3();
        if (ff3Stream != null) {
            try (RandomAccessRead randomAccessRead = ff3Stream.getCOSObject().createView()) {
                if (randomAccessRead.length() == 0) {
                    LOG.error("Invalid data for embedded Type1C font " + getName());
                } else {
                    // note: this could be an OpenType file, fortunately CFFParser can handle that
                    CFFParser cffParser = new CFFParser();
                    CFFFont parsedCffFont = cffParser.parse(randomAccessRead).get(0);
                    if (parsedCffFont instanceof CFFType1Font) {
                        cffEmbedded = ((CFFType1Font) (parsedCffFont));
                    } else {
                        LOG.error("Expected CFFType1Font, got " + parsedCffFont.getClass().getSimpleName());
                        fontIsDamaged = true;
                    }
                }
            } catch (IOException e) {
                LOG.error("Can't read the embedded Type1C font " + getName(), e);
                fontIsDamaged = true;
            }
        }
    }
    isDamaged = fontIsDamaged;
    cffFont = cffEmbedded;
    if (cffFont != null) {
        genericFont = cffFont;
        isEmbedded = true;
    } else {
        String baseFont = getBaseFont();
        FontMapping<FontBoxFont> mapping = FontMappers.instance().getFontBoxFont(baseFont, fd);
        genericFont = mapping.getFont();
        if (mapping.isFallback()) {
            LOG.warn((("Using fallback font " + genericFont.getName()) + " for ") + baseFont);
        }
        isEmbedded = false;
    }
    readEncoding();
    fontMatrixTransform = getFontMatrix().createAffineTransform();
    fontMatrixTransform.scale(1000, 1000);
}

/**
 * Reads the Encoding from the Font dictionary or the embedded or substituted font file.
 * Must be called at the end of any subclass constructors.
 *
 * @throws IOException
 * 		if the font file could not be read
 */
protected void readEncoding() throws IOException {
    COSBase encodingBase = dict.getDictionaryObject(COSName.ENCODING);
    if (encodingBase instanceof COSName) {
        COSName encodingName = ((COSName) (encodingBase));
        if (FontName.ZAPF_DINGBATS.getName().equals(getName()) && (!isEmbedded())) {
            // PDFBOX- and PDF.js issue 16464: ignore other encodings
            // this segment will work only if readEncoding() is called after the data
            // for getName() and isEmbedded() is available
            this.encoding = ZapfDingbatsEncoding.INSTANCE;
        } else {
            this.encoding = Encoding.getInstance(encodingName);
            if (this.encoding == null) {
                LOG.warn("Unknown encoding: " + encodingName.getName());
                this.encoding = readEncodingFromFont();// fallback

            }
        }
    } else if (encodingBase instanceof COSDictionary) {
        COSDictionary encodingDict = ((COSDictionary) (encodingBase));
        Encoding builtIn = null;
        Boolean symbolic = getSymbolicFlag();
        COSName baseEncoding = encodingDict.getCOSName(COSName.BASE_ENCODING);
        boolean hasValidBaseEncoding = (baseEncoding != null) && (Encoding.getInstance(baseEncoding) != null);
        if ((!hasValidBaseEncoding) && Boolean.TRUE.equals(symbolic)) {
            builtIn = readEncodingFromFont();
        }
        if (symbolic == null) {
            symbolic = false;
        }
        this.encoding = new DictionaryEncoding(encodingDict, !symbolic, builtIn);
    } else {
        this.encoding = readEncodingFromFont();
    }
    // normalise the standard 14 name, e.g "Symbol,Italic" -> "Symbol"
    FontName standard14Name = Standard14Fonts.getMappedFontName(getName());
    assignGlyphList(standard14Name);
}

