/**
 * Create a PDImageXObject from an image byte array. This overloaded version allows providing
 * a custom factory to handle specific image formats, such as BMP and GIF, or to act as a
 * fallback strategy when the default converters (e.g., for PNG or TIFF) fail.
 *
 * @param document
 * 		the document that shall use this PDImageXObject.
 * @param byteArray
 * 		bytes from an image file.
 * @param name
 * 		name of image file for exception messages, can be null.
 * @param customFactory
 * 		optional factory used to handle BMP, GIF, or fallback cases
 * 		(e.g., for PNG or TIFF). If {@code null}, this method delegates to
 * 		{@link #createFromByteArray(PDDocument, byte[], String)}.
 * @return a PDImageXObject.
 * @throws IOException
 * 		if there is an error when reading the file or creating the
 * 		PDImageXObject.
 * @throws IllegalArgumentException
 * 		if the image type is not supported.
 */
public static PDImageXObject createFromByteArray(PDDocument document, byte[] byteArray, String name, CustomFactory customFactory) throws IOException {
    FileType fileType = FileTypeDetector.detectFileType(byteArray);
    if (fileType == null) {
        throw new IllegalArgumentException("Image type not supported: " + name);
    }
    if (fileType == FileType.JPEG) {
        return JPEGFactory.createFromByteArray(document, byteArray);
    }
    if (fileType == FileType.PNG) {
        // Try to directly convert the image without recoding it.
        // PATH: Test should invoke the next PNGConverter.convertPNGImage(...) [step in execution path]
        PDImageXObject image = PNGConverter.convertPNGImage(document, byteArray);
        if (image != null) {
            return image;
        }
    }
    if (fileType == FileType.TIFF) {
        try {
            return CCITTFactory.createFromByteArray(document, byteArray);
        } catch (IOException ex) {
            LOG.debug("Reading as TIFF failed, setting fileType to PNG", ex);
            // Plan B: try reading with ImageIO
            // common exception:
            // First image in tiff is not CCITT T4 or T6 compressed
            fileType = FileType.PNG;
        }
    }
    if (((fileType == FileType.BMP) || (fileType == FileType.GIF)) || (fileType == FileType.PNG)) {
        if (customFactory != null) {
            return customFactory.createFromByteArray(document, byteArray);
        }
        ByteArrayInputStream bais = new ByteArrayInputStream(byteArray);
        BufferedImage bim = ImageIO.read(bais);
        return LosslessFactory.createFromImage(document, bim);
    }
    throw new IllegalArgumentException((("Image type " + fileType) + " not supported: ") + name);
}

/**
 * Try to convert a PNG into a PDImageXObject. If for any reason the PNG can not
 * be converted, null is returned.
 * <p>
 * This usually means the PNG structure is damaged (CRC error, etc.) or it uses
 * some features which can not be mapped to PDF.
 *
 * @param doc
 * 		the document to put the image in
 * @param imageData
 * 		the byte data of the PNG
 * @return null or the PDImageXObject built from the png
 */
static PDImageXObject convertPNGImage(PDDocument doc, byte[] imageData) throws IOException {
    PNGConverterState state = parsePNGChunks(imageData);
    if (!checkConverterState(state)) {
        // There is something wrong, we can't convert this PNG
        return null;
    }
    // PATH: Test should invoke the next PNGConverter.convertPng(...) [step in execution path]
    return convertPng(doc, state);
}

/**
 * Convert the image using the state.
 *
 * @param doc
 * 		the document to put the image in
 * @param state
 * 		the parser state containing the PNG chunks.
 * @return null or the converted image
 */
private static PDImageXObject convertPng(PDDocument doc, PNGConverterState state) throws IOException {
    Chunk ihdr = state.IHDR;
    int ihdrStart = ihdr.start;
    int width = readInt(ihdr.bytes, ihdrStart);
    int height = readInt(ihdr.bytes, ihdrStart + 4);
    int bitDepth = ihdr.bytes[ihdrStart + 8] & 0xff;
    int colorType = ihdr.bytes[ihdrStart + 9] & 0xff;
    int compressionMethod = ihdr.bytes[ihdrStart + 10] & 0xff;
    int filterMethod = ihdr.bytes[ihdrStart + 11] & 0xff;
    int interlaceMethod = ihdr.bytes[ihdrStart + 12] & 0xff;
    if (((((bitDepth != 1) && (bitDepth != 2)) && (bitDepth != 4)) && (bitDepth != 8)) && (bitDepth != 16)) // PATH: Test should invoke the next Log.error(...) [step in execution path]
    {
        LOG.error(String.format("Invalid bit depth %d.", bitDepth));
        return null;
    }
    if ((width <= 0) || (height <= 0)) {
        LOG.error(String.format("Invalid image size %d x %d", width, height));
        return null;
    }
    if (compressionMethod != 0) {
        LOG.error(String.format("Unknown PNG compression method %d.", compressionMethod));
        return null;
    }
    if (filterMethod != 0) {
        LOG.error(String.format("Unknown PNG filtering method %d.", compressionMethod));
        return null;
    }
    if (interlaceMethod != 0) {
        LOG.debug(String.format("Can't handle interlace method %d.", interlaceMethod));
        return null;
    }
    state.width = width;
    state.height = height;
    state.bitsPerComponent = bitDepth;
    switch (colorType) {
        case 0 :
            // Grayscale
            LOG.debug("Can't handle grayscale yet.");
            return null;
        case 2 :
            // Truecolor
            if (state.tRNS != null) {
                LOG.debug("Can't handle images with transparent colors.");
                return null;
            }
            return buildImageObject(doc, state);
        case 3 :
            // Indexed image
            return buildIndexImage(doc, state);
        case 4 :
            // Grayscale with alpha.
            LOG.debug("Can't handle grayscale with alpha, would need to separate alpha from image data");
            return null;
        case 6 :
            // Truecolor with alpha.
            LOG.debug("Can't handle truecolor with alpha, would need to separate alpha from image data");
            return null;
        default :
            LOG.error("Unknown PNG color type " + colorType);
            return null;
    }
}

