private void processStreamOperators(PDContentStream contentStream) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(contentStream);
    Object token = parser.parseNextToken();
    boolean isFirstOperator = true;
    boolean oldShouldProcessColorOperators = shouldProcessColorOperators;
    shouldProcessColorOperators = true;
    if ((contentStream instanceof PDTilingPattern) && (((PDTilingPattern) (contentStream)).getPaintType() == PDTilingPattern.PAINT_UNCOLORED)) {
        shouldProcessColorOperators = false;
    }
    try {
        while (token != null) {
            if (token instanceof Operator) {
                if ((isFirstOperator && (contentStream instanceof PDType3CharProc)) && OperatorName.TYPE3_D1.equals(((Operator) (token)).getName())) {
                    shouldProcessColorOperators = false;
                }
                isFirstOperator = false;
                processOperator(((Operator) (token)), arguments);
                arguments.clear();
            } else {
                arguments.add(((COSBase) (token)));
            }
            token = parser.parseNextToken();
        } 
    } finally {
        shouldProcessColorOperators = oldShouldProcessColorOperators;
    }
}

/**
 * Process the given tiling pattern. Allows the pattern matrix to be overridden for custom
 * rendering.
 *
 * @param tilingPattern
 * 		the tiling pattern
 * @param color
 * 		color to use, if this is an uncoloured pattern, otherwise null.
 * @param colorSpace
 * 		color space to use, if this is an uncoloured pattern, otherwise null.
 * @param patternMatrix
