protected COSName parseCOSName() throws IOException {
    readExpectedChar('/');
    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    int c = source.read();
    while (!isEndOfName(c)) {
        final int ch = c;
        if (ch == '#') {
            int ch1 = source.read();
            int ch2 = source.read();
            // Prior to PDF v1.2, the # was not a special character.  Also,
            // it has been observed that various PDF tools do not follow the
            // spec with respect to the # escape, even though they report
            // PDF versions of 1.2 or later.  The solution here is that we
            // interpret the # as an escape only when it is followed by two
            // valid hex digits.
            if (isHexDigit(((char) (ch1))) && isHexDigit(((char) (ch2)))) {
                String hex = Character.toString(((char) (ch1))) + ((char) (ch2));
                try {
                    buffer.write(Integer.parseInt(hex, 16));
                } catch (NumberFormatException e) {
                    throw new IOException(("Error: expected hex digit, actual='" + hex) + "'", e);
                }
                c = source.read();
            } else {
                // check for premature EOF
                if ((ch2 == (-1)) || (ch1 == (-1))) // PATH: Test should invoke the next Log.error(...) [step in execution path]
                {
                    LOG.error("Premature EOF in BaseParser#parseCOSName");
                    c = -1;
