    rect.setLowerLeftY(Math.min(minY - max, rect.getLowerLeftY()));
    rect.setUpperRightX(Math.max(maxX + max, rect.getUpperRightX()));
    rect.setUpperRightY(Math.max(maxY + max, rect.getUpperRightY()));
