            float y = pathsArray[(i * 2) + 1];
            if (i == 0) {
                if (SHORT_STYLES.contains(lineEndingStyle)) {
                    // modify coordinate to shorten the segment
                    // https://stackoverflow.com/questions/7740507/extend-a-line-segment-a-specific-distance
