                    float y1 = pathsArray[3];
                    float len = ((float) (Math.sqrt(Math.pow(x - x1, 2) + Math.pow(y - y1, 2))));
                    if (Float.compare(len, 0) != 0) {
                        x += ((x1 - x) / len) * ab.width;
                        y += ((y1 - y) / len) * ab.width;
                    }
                }
                cs.moveTo(x, y);
            } else {
                cs.lineTo(x, y);
