/**
 * Write a comment line.
 *
 * @param comment
 * 		the comment to be added to the content stream
 * @throws IOException
 * 		If the content stream could not be written.
 * @throws IllegalArgumentException
 * 		If the comment contains a newline. This is not allowed, because the next line
 * 		could be ordinary PDF content.
 */
public void addComment(String comment) throws IOException {
    if ((comment.indexOf('\n') >= 0) || (comment.indexOf('\r') >= 0)) {
        throw new IllegalArgumentException("comment should not include a newline");
    }
    outputStream.write('%');
    outputStream.write(comment.getBytes(StandardCharsets.US_ASCII));
    outputStream.write('\n');
}

