 *
 * @param value
 * 		Name of option to select
 * @throws IOException
 * 		if the value could not be set
 * @throws IllegalArgumentException
 * 		if the value is not a valid option.
 */
@Override
public void setValue(String value) throws IOException // PATH: Test should invoke the next PDTerminalField.applyChange(...) [step in execution path]
{
    checkValue(value);
    // if there are export values/an Opt entry there is a different
    // approach to setting the value
    if (!getExportValues().isEmpty()) {
        updateByOption(value);
    } else {
        updateByValue(value);
    }
    applyChange();
}

/**
 * Applies a value change to the field. Generates appearances if required and raises events.
 *
 * @throws IOException
 * 		if the appearance couldn't be generated
 */
protected final void applyChange() throws IOException // PATH: Test should invoke the next PDComboBox.constructAppearances(...) [step in execution path]
{
    constructAppearances();
    // if we supported JavaScript we would raise a field changed event here
}

@Override
void constructAppearances() throws IOException {
    AppearanceGeneratorHelper apHelper;
    apHelper = new AppearanceGeneratorHelper(this);
    List<String> values = getValue();
    if (!values.isEmpty()) {
        apHelper.setAppearanceValue(values.get(0));
    } else {
        apHelper.setAppearanceValue("");
    }
}

