 * @param genNum
 * 		The object generation number.
 * @throws IOException
 * 		If an error occurs writing the new string.
 */
public void encryptString(COSString string, long objNum, int genNum) throws IOException // PATH: Test should invoke the next SecurityHandler.encryptData(...) [step in execution path]
{
    ByteArrayInputStream data = new ByteArrayInputStream(string.getBytes());
    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    /* encrypt */
    encryptData(objNum, genNum, data, buffer, false);
    string.setValue(buffer.toByteArray());
}

/**
 * Encrypt or decrypt a set of data.
 *
 * @param objectNumber
 * 		The data object number.
 * @param genNumber
 * 		The data generation number.
 * @param data
 * 		The data to encrypt.
 * @param output
 * 		The output to write the encrypted data to.
 * @param decrypt
 * 		true to decrypt the data, false to encrypt it.
 * @throws IOException
 * 		If there is an error reading the data.
 */
private void encryptData(long objectNumber, long genNumber, InputStream data, OutputStream output, boolean decrypt) throws IOException {
    // Determine whether we're using Algorithm 1 (for RC4 and AES-128), or 1.A (for AES-256)
    if (useAES && (encryptionKey.length == 32)) // PATH: Test should invoke the next SecurityHandler.encryptDataAES256(...) [step in execution path]
    {
        encryptDataAES256(data, output, decrypt);
    } else {
        byte[] finalKey = calcFinalKey(objectNumber, genNumber);
        if (useAES) {
            encryptDataAESother(finalKey, data, output, decrypt);
        } else {
            encryptDataRC4(finalKey, data, output);
        }
    }
    output.flush();
}

/**
 * Encrypt or decrypt data with AES256.
 *
 * @param data
 * 		The data to encrypt.
 * @param output
 * 		The output to write the encrypted data to.
 * @param decrypt
 * 		true to decrypt the data, false to encrypt it.
 * @throws IOException
 * 		If there is an error reading the data.
 */
private void encryptDataAES256(InputStream data, OutputStream output, boolean decrypt) throws IOException {
    byte[] iv = new byte[16];
    if (!prepareAESInitializationVector(decrypt, iv, data, output)) {
        return;
    }
    Cipher cipher;
    try {
        cipher = createCipher(this.encryptionKey, iv, decrypt);
    } catch (GeneralSecurityException e) {
        throw new IOException(e);
    }
    try (CipherInputStream cis = new CipherInputStream(data, cipher)) {
        IOUtils.copy(cis, output);
    } catch (IOException exception) {
        // starting with java 8 the JVM wraps an IOException around a GeneralSecurityException
        // it should be safe to swallow a GeneralSecurityException
        if (!(exception.getCause() instanceof GeneralSecurityException)) {
            throw exception;
        }
        LOG.debug("A GeneralSecurityException occurred when decrypting some stream data", exception);
    }
}

