protected void operatorException(Operator operator, List<COSBase> operands, IOException exception) throws IOException {
    if (((exception instanceof MissingOperandException) || (exception instanceof MissingResourceException)) || (exception instanceof MissingImageReaderException)) {
        LOG.error(exception.getMessage(), exception);
    } else if (exception instanceof EmptyGraphicsStackException) {
        LOG.warn(exception.getMessage(), exception);
    } else if (operator.getName().equals("Do")) {
        // todo: this too forgiving, but PDFBox has always worked this way for DrawObject
        // some careful refactoring is needed
        LOG.warn(exception.getMessage(), exception);
    } else if (exception.getCause() instanceof DataFormatException) {
        LOG.warn(exception.getMessage(), exception);
    } else {
