            setEOFLookupRange(Integer.parseInt(eofLookupRangeStr));
        } catch (NumberFormatException nfe) {
            LOG.warn(((("System property " + SYSPROP_EOFLOOKUPRANGE) + " does not contain an integer value, but: '") + eofLookupRangeStr) + "'");
