/**
 * Prepare for decryption.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		if something went wrong
 */
protected void prepareDecryption() throws IOException {
    if (encryption != null) {
        return;
    }
    COSDictionary encryptionDictionary = document.getEncryptionDictionary();
    if (encryptionDictionary == null) {
        return;
    }
    try {
        encryption = new PDEncryption(encryptionDictionary);
        DecryptionMaterial decryptionMaterial;
        if (keyStoreInputStream != null) {
            KeyStore ks = KeyStore.getInstance("PKCS12");
            ks.load(keyStoreInputStream, password.toCharArray());
            decryptionMaterial = new PublicKeyDecryptionMaterial(ks, keyAlias, password);
        } else {
            decryptionMaterial = new StandardDecryptionMaterial(password);
        }
        securityHandler = encryption.getSecurityHandler();
        securityHandler.prepareForDecryption(encryption, document.getDocumentID(), decryptionMaterial);
        accessPermission = securityHandler.getCurrentAccessPermission();
    } catch (IOException e) {
        throw e;
    } catch (GeneralSecurityException e) {
        throw new IOException(("Error (" + e.getClass().getSimpleName()) + ") while creating security handler for decryption", e);
    } finally {
        if (keyStoreInputStream != null) {
            IOUtils.closeQuietly(keyStoreInputStream);
        }
    }
}

/**
 * Change the parser leniency flag.
 *
 * This method can only be called before the parsing of the file.
 *
 * @param lenient
 * 		try to handle malformed PDFs.
 */
protected void setLenient(boolean lenient) {
    if (initialParseDone) {
        throw new IllegalArgumentException("Cannot change leniency after parsing");
    }
    this.isLenient = lenient;
}

