/**
 * This will parse the stream and populate the FDFDocument object.
 *
 * @return the parsed FDFDocument
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public FDFDocument parse() throws IOException {
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try {
        if (// PATH: Test should invoke the next COSParser.parseFDFHeader(...) [step in execution path]
        !parseFDFHeader()) {
            throw new IOException("Error: Header doesn't contain versioninfo");
        }
        initialParse();
        exceptionOccurred = false;
        return new FDFDocument(document, source);
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * Parse the header of a fdf.
 *
 * @return true if a FDF header was found
 * @throws IOException
 * 		if something went wrong
 */
protected boolean parseFDFHeader() throws IOException {
    // PATH: Test should invoke the next COSParser.parseHeader(...) [step in execution path]
    return parseHeader(FDF_HEADER, FDF_DEFAULT_VERSION);
}

private boolean parseHeader(String headerMarker, String defaultVersion) throws IOException {
    // read first line
    String header = readLine();
    // some pdf-documents are broken and the pdf-version is in one of the following lines
    if (!header.contains(headerMarker)) {
        header = readLine();
        while (!header.contains(headerMarker)) {
            // if a line starts with a digit, it has to be the first one with data in it
            if ((header.length() > 0) && Character.isDigit(header.charAt(0))) {
                break;
            }
            header = readLine();
        } 
    }
    // nothing found
    if (!header.contains(headerMarker)) {
        source.seek(0);
        return false;
    }
    // sometimes there is some garbage in the header before the header
    // actually starts, so lets try to find the header first.
    int headerStart = header.indexOf(headerMarker);
    // greater than zero because if it is zero then there is no point of trimming
    if (headerStart > 0) {
        // trim off any leading characters
        header = header.substring(headerStart);
    }
    // This is used if there is garbage after the header on the same line
    if (header.startsWith(headerMarker) && (!header.matches(headerMarker + "\\d.\\d"))) {
