private Paint applySoftMaskToPaint(Paint parentPaint, PDSoftMask softMask) throws IOException {
    if ((softMask == null) || (softMask.getGroup() == null)) {
        return parentPaint;
    }
    PDColor backdropColor = null;
    if (COSName.LUMINOSITY.equals(softMask.getSubType())) {
        COSArray backdropColorArray = softMask.getBackdropColor();
        if (backdropColorArray != null) {
            PDTransparencyGroup form = softMask.getGroup();
            PDColorSpace colorSpace = form.getGroup().getColorSpace(form.getResources());
            // PDFBOX-5795
            if ((colorSpace != null) && (colorSpace.getNumberOfComponents() == backdropColorArray.size())) {
                backdropColor = new PDColor(backdropColorArray, colorSpace);
            }
        }
    }
    TransparencyGroup transparencyGroup = new TransparencyGroup(softMask.getGroup(), true, softMask.getInitialTransformationMatrix(), backdropColor);
    BufferedImage image = transparencyGroup.getImage();
    if (image == null) {
        // Adobe Reader ignores empty softmasks instead of using bc color
        // sample file: PDFJS-6967_reduced_outside_softmask.pdf
        return parentPaint;
    }
    BufferedImage gray = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_BYTE_GRAY);
    if (COSName.ALPHA.equals(softMask.getSubType())) {
        gray.setData(image.getAlphaRaster());
    } else if (COSName.LUMINOSITY.equals(softMask.getSubType())) {
        Graphics g = gray.getGraphics();
        g.drawImage(image, 0, 0, null);
        g.dispose();
    } else {
        throw new IOException("Invalid soft mask subtype.");
    }
    gray = adjustImage(gray);
    Rectangle2D tpgBounds = transparencyGroup.getBounds();
    return new SoftMask(parentPaint, gray, tpgBounds, backdropColor, softMask.getTransferFunction());
}

/**
 * Creates a new soft mask paint.
 *
 * @param paint
 * 		underlying paint.
 * @param mask
 * 		soft mask
 * @param bboxDevice
 * 		bbox of the soft mask in the underlying Graphics2D device space
 * @param backdropColor
 * 		the color to be used outside the transparency group’s bounding box; if
 * 		null, black will be used.
 * @param transferFunction
 * 		the transfer function, may be null.
 */
(Paint paint, BufferedImage mask, Rectangle2D bboxDevice, PDColor backdropColor, PDFunction transferFunction) {
    this.paint = paint;
    this.mask = mask;
    this.bboxDevice = bboxDevice;
    if (transferFunction instanceof PDFunctionTypeIdentity) {
        this.transferFunction = null;
    } else {
        this.transferFunction = transferFunction;
    }
    if (backdropColor != null) {
        try {
            Color color = new Color(backdropColor.toRGB());
            // http://stackoverflow.com/a/25463098/535646
            bc = (((299 * color.getRed()) + (587 * color.getGreen())) + (114 * color.getBlue())) / 1000;
        } catch (IOException ex) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            // keep default
            LOG.debug("Couldn't convert backdropColor to RGB - keeping default", ex);
        }
    }
}

