/**
 * Encodes the given string for use in a PDF content stream.
 *
 * @param text
 * 		Any Unicode text.
 * @return Array of PDF content stream bytes.
 * @throws IOException
 * 		If the text could not be encoded.
 * @throws IllegalArgumentException
 * 		if a character isn't supported by the font.
 */
public final byte[] encode(String text) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(32, text.length()));
    int offset = 0;
    while (offset < text.length()) {
        int codePoint = text.codePointAt(offset);
        // multi-byte encoding with 1 to 4 bytes
        // PATH: Test should invoke the next PDType1Font.encode(...) [step in execution path]
        byte[] bytes = encode(codePoint);
        out.write(bytes);
        offset += Character.charCount(codePoint);
    } 
    return out.toByteArray();
}

@Override
protected byte[] encode(int unicode) throws IOException {
    byte[] bytes = codeToBytesMap.get(unicode);
    if (bytes != null) {
        return bytes;
    }
    String name = getGlyphList().codePointToName(unicode);
    if (isStandard14()) {
        // genericFont not needed, thus simplified code
        // this is important on systems with no installed fonts
        if (!encoding.contains(name)) {
            throw new IllegalArgumentException(String.format("U+%04X ('%s') is not available in the font %s, encoding: %s", unicode, name, getName(), encoding.getEncodingName()));
        }
        if (".notdef".equals(name)) {
            throw new IllegalArgumentException(String.format("No glyph for U+%04X in the font %s", unicode, getName()));
        }
    } else {
        if (!encoding.contains(name)) {
            throw new IllegalArgumentException(String.format("U+%04X ('%s') is not available in the font %s (generic: %s), encoding: %s", unicode, name, getName(), genericFont.getName(), encoding.getEncodingName()));
        }
        // PATH: Test should invoke the next PDType1Font.getNameInFont(...) [step in execution path]
        String nameInFont = getNameInFont(name);
        if (".notdef".equals(nameInFont) || (!genericFont.hasGlyph(nameInFont))) {
            throw new IllegalArgumentException(String.format("No glyph for U+%04X in the font %s (generic: %s)", unicode, getName(), genericFont.getName()));
        }
    }
    Map<String, Integer> inverted = encoding.getNameToCodeMap();
    int code = inverted.get(name);
    if (code < 0) {
        throw new IllegalArgumentException(String.format("U+%04X ('%s') is not available in the font %s (generic: %s), encoding: %s", unicode, name, getName(), genericFont.getName(), encoding.getEncodingName()));
    }
    bytes = new byte[]{ ((byte) (code)) };
    codeToBytesMap.put(unicode, bytes);
    return bytes;
}

/**
 * Maps a PostScript glyph name to the name in the underlying font, for example when
 * using a TTF font we might map "W" to "uni0057".
 */
private String getNameInFont(String name) throws IOException {
    if (isEmbedded() || genericFont.hasGlyph(name)) {
        return name;
    }
    // try alternative name
    String altName = ALT_NAMES.get(name);
    if (((altName != null) && (!name.equals(".notdef"))) && genericFont.hasGlyph(altName)) {
        return altName;
    }
    // try unicode name
    String unicodes = getGlyphList().toUnicode(name);
    if ((unicodes != null) && (unicodes.length() == 1)) {
        String uniName = getUniNameOfCodePoint(unicodes.codePointAt(0));
        if (genericFont.hasGlyph(uniName)) {
            return uniName;
        }
        // PDFBOX-4017: no postscript table on Windows 10, and the low uni00NN
        // names are not found in Symbol font. What works is using the PDF code plus 0xF000
        // while disregarding encoding from the PDF (because of file from PDFBOX-1606,
        // makes sense because this segment is about finding the name in a standard font)
        // TODO bring up better solution than this
        if ("SymbolMT".equals(genericFont.getName())) {
            Integer code = SymbolEncoding.INSTANCE.getNameToCodeMap().get(name);
            if (code != null) {
                uniName = getUniNameOfCodePoint(code + 0xf000);
                if (genericFont.hasGlyph(uniName)) {
                    return uniName;
                }
            }
        }
    }
    return ".notdef";
}

