 * @param operator
 * 		The operation to perform.
 * @param operands
 * 		The list of arguments.
 * @throws IOException
 * 		If there is an error processing the operation.
 */
protected void processOperator(Operator operator, List<COSBase> operands) throws IOException {
    String name = operator.getName();
    OperatorProcessor processor = operators.get(name);
    if (processor != null) {
        try {
            processor.process(operator, operands);
        } catch (IOException e) {
            operatorException(operator, operands, e);
        }
    } else {
        unsupportedOperator(operator, operands);
    }
}

/**
 * This will initialize and process the contents of the stream.
 *
 * @param page
 * 		the page to process
 * @throws IOException
 * 		if there is an error accessing the stream
 */
public void processPage(PDPage page) throws IOException {
    initPage(page);
    if (page.hasContents()) {
        isProcessingPage = true;
        processStream(page);
        isProcessingPage = false;
    }
}

/**
 * Process a content stream.
 *
 * @param contentStream
 * 		the content stream
 * @throws IOException
 * 		if there is an exception while processing the stream
 */
private void processStream(PDContentStream contentStream) throws IOException {
    PDResources parent = pushResources(contentStream);
    Deque<PDGraphicsState> savedStack = saveGraphicsStack();
    Matrix parentMatrix = initialMatrix;
    PDGraphicsState graphicsState = getGraphicsState();
    // transform the CTM using the stream's matrix
    graphicsState.getCurrentTransformationMatrix().concatenate(contentStream.getMatrix());
    // the stream's initial matrix includes the parent CTM, e.g. this allows a scaled form
    initialMatrix = graphicsState.getCurrentTransformationMatrix().clone();
    // clip to bounding box
    PDRectangle bbox = contentStream.getBBox();
    clipToRect(bbox);
    try {
        processStreamOperators(contentStream);
    } finally {
        initialMatrix = parentMatrix;
        restoreGraphicsStack(savedStack);
        popResources(parent);
    }
}

/**
 * Processes the operators of the given content stream.
 *
 * @param contentStream
 * 		to content stream to parse.
 * @throws IOException
 * 		if there is an error reading or parsing the content stream.
 */
private void processStreamOperators(PDContentStream contentStream) throws IOException {
    List<COSBase> arguments = new ArrayList<>();
    PDFStreamParser parser = new PDFStreamParser(contentStream);
    Object token = parser.parseNextToken();
    boolean isFirstOperator = true;
    boolean oldShouldProcessColorOperators = shouldProcessColorOperators;
    shouldProcessColorOperators = true;
    if ((contentStream instanceof PDTilingPattern) && (((PDTilingPattern) (contentStream)).getPaintType() == PDTilingPattern.PAINT_UNCOLORED)) {
        shouldProcessColorOperators = false;
    }
    try {
        while (token != null) {
            if (token instanceof Operator) {
                if ((isFirstOperator && (contentStream instanceof PDType3CharProc)) && OperatorName.TYPE3_D1.equals(((Operator) (token)).getName())) {
                    shouldProcessColorOperators = false;
                }
                isFirstOperator = false;
                processOperator(((Operator) (token)), arguments);
                arguments.clear();
            } else {
                arguments.add(((COSBase) (token)));
            }
            token = parser.parseNextToken();
        } 
    } finally {
        shouldProcessColorOperators = oldShouldProcessColorOperators;
    }
}

/**
 * Process the given tiling pattern. Allows the pattern matrix to be overridden for custom
 * rendering.
 *
 * @param tilingPattern
 * 		the tiling pattern
 * @param color
 * 		color to use, if this is an uncoloured pattern, otherwise null.
 * @param colorSpace
 * 		color space to use, if this is an uncoloured pattern, otherwise null.
 * @param patternMatrix
 * 		the pattern matrix, may be overridden for custom rendering.
 * @throws IOException
 * 		if there is an error reading or parsing the tiling pattern content stream.
 */
protected final void processTilingPattern(PDTilingPattern tilingPattern, PDColor color, PDColorSpace colorSpace, Matrix patternMatrix) throws IOException {
    PDResources parent = pushResources(tilingPattern);
    Matrix parentMatrix = initialMatrix;
    initialMatrix = Matrix.concatenate(initialMatrix, patternMatrix);
    // save the original graphics state
    Deque<PDGraphicsState> savedStack = saveGraphicsStack();
    // save a clean state (new clipping path, line path, etc.)
    PDRectangle tilingBBox = tilingPattern.getBBox();
    Rectangle2D bbox = tilingBBox.transform(patternMatrix).getBounds2D();
    PDRectangle rect = new PDRectangle(((float) (bbox.getX())), ((float) (bbox.getY())), ((float) (bbox.getWidth())), ((float) (bbox.getHeight())));
    graphicsStack.push(new PDGraphicsState(rect));
    PDGraphicsState graphicsState = getGraphicsState();
    // non-colored patterns have to be given a color
    if (colorSpace != null) {
        color = new PDColor(color.getComponents(), colorSpace);
        graphicsState.setNonStrokingColorSpace(colorSpace);
        graphicsState.setNonStrokingColor(color);
        graphicsState.setStrokingColorSpace(colorSpace);
        graphicsState.setStrokingColor(color);
    }
    // transform the CTM using the stream's matrix
    graphicsState.getCurrentTransformationMatrix().concatenate(patternMatrix);
    // clip to bounding box
    clipToRect(tilingBBox);
    try {
        processStreamOperators(tilingPattern);
    } finally {
        initialMatrix = parentMatrix;
        restoreGraphicsStack(savedStack);
        popResources(parent);
    }
}

/**
 * Processes a transparency group stream.
 *
 * @param group
 * 		transparency group to be processed
 * @throws IOException
 * 		if the transparency group cannot be processed
 */
protected void processTransparencyGroup(PDTransparencyGroup group) throws IOException {
    if (currentPage == null) {
        throw new IllegalStateException("No current page, call " + "#processChildStream(PDContentStream, PDPage) instead");
    }
    PDResources parent = pushResources(group);
    Deque<PDGraphicsState> savedStack = saveGraphicsStack();
    Matrix parentMatrix = initialMatrix;
    PDGraphicsState graphicsState = getGraphicsState();
    // the stream's initial matrix includes the parent CTM, e.g. this allows a scaled form
    initialMatrix = graphicsState.getCurrentTransformationMatrix().clone();
    // transform the CTM using the stream's matrix
    graphicsState.getCurrentTransformationMatrix().concatenate(group.getMatrix());
    // Before execution of the transparency group XObject’s content stream,
    // the current blend mode in the graphics state shall be initialized to Normal,
    // the current stroking and nonstroking alpha constants to 1.0, and the current soft mask to None.
    graphicsState.setBlendMode(BlendMode.NORMAL);
    graphicsState.setAlphaConstant(1);
    graphicsState.setNonStrokeAlphaConstant(1);
    graphicsState.setSoftMask(null);
    // clip to bounding box
    clipToRect(group.getBBox());
    try {
        processStreamOperators(group);
    } finally {
        initialMatrix = parentMatrix;
        restoreGraphicsStack(savedStack);
        popResources(parent);
    }
}

/**
 * Restores the entire graphics stack.
 *
 * @param snapshot
 * 		the graphics state to be restored
 */
protected final void restoreGraphicsStack(Deque<PDGraphicsState> snapshot) {
    graphicsStack = snapshot;
}

/**
 * Pops the current graphics state from the stack.
 */
public void restoreGraphicsState() {
    graphicsStack.pop();
}

/**
 * Pushes the current graphics state to the stack.
 */
public void saveGraphicsState() {
    graphicsStack.push(graphicsStack.peek().clone());
}

/**
 * Process text from the PDF Stream. You should override this method if you want to
 * perform an action when encoded text is being processed.
 *
 * @param string
 * 		the encoded text
 * @throws IOException
 * 		if there is an error processing the string
 */
protected void showText(byte[] string) throws IOException {
    PDGraphicsState state = getGraphicsState();
    PDTextState textState = state.getTextState();
    // get the current font
    PDFont font = textState.getFont();
    if (font == null) {
        LOG.warn("No current font, will use default");
        font = getDefaultFont();
    }
    float fontSize = textState.getFontSize();
    float horizontalScaling = textState.getHorizontalScaling() / 100.0F;
    float charSpacing = textState.getCharacterSpacing();
    // put the text state parameters into matrix form
    Matrix parameters = // 0
    // 0
    new Matrix(fontSize * horizontalScaling, 0, 0, fontSize, 0, textState.getRise());// 1

    Matrix textMatrix = state.getTextMatrix();
    // read the stream until it is empty
    InputStream in = new ByteArrayInputStream(string);
    while (in.available() > 0) {
        // decode a character
        int before = in.available();
        int code = font.readCode(in);
        int codeLength = before - in.available();
        // Word spacing shall be applied to every occurrence of the single-byte character code
        // 32 in a string when using a simple font or a composite font that defines code 32 as
        // a single-byte code.
        float wordSpacing = 0;
        if ((codeLength == 1) && (code == 32)) {
            wordSpacing += textState.getWordSpacing();
        }
        // text rendering matrix (text space -> device space)
        Matrix ctm = state.getCurrentTransformationMatrix();
        Matrix textRenderingMatrix = parameters.multiply(textMatrix).multiply(ctm);
        // get glyph's position vector if this is vertical text
        // changes to vertical text should be tested with PDFBOX-2294 and PDFBOX-1422
        if (font.isVertical()) {
            // position vector, in text space
            Vector v = font.getPositionVector(code);
            // apply the position vector to the horizontal origin to get the vertical origin
            textRenderingMatrix.translate(v);
        }
        // get glyph's horizontal and vertical displacements, in text space
        Vector w = font.getDisplacement(code);
        // process the decoded glyph
        showGlyph(textRenderingMatrix, font, code, w);
        // calculate the combined displacements
        float tx;
        float ty;
        if (font.isVertical()) {
            tx = 0;
            ty = ((w.getY() * fontSize) + charSpacing) + wordSpacing;
        } else {
            tx = (((w.getX() * fontSize) + charSpacing) + wordSpacing) * horizontalScaling;
            ty = 0;
        }
        // update the text matrix
        textMatrix.translate(tx, ty);
    } 
}

/**
 * Called when a string of text with spacing adjustments is to be shown.
 *
 * @param array
 * 		array of encoded text strings and adjustments
 * @throws IOException
 * 		if there was an error showing the text
 */
public void showTextStrings(COSArray array) throws IOException {
    PDTextState textState = getGraphicsState().getTextState();
    float fontSize = textState.getFontSize();
    float horizontalScaling = textState.getHorizontalScaling() / 100.0F;
    PDFont font = textState.getFont();
    boolean isVertical = false;
    if (font != null) {
        isVertical = font.isVertical();
    }
    for (COSBase obj : array) {
        if (obj instanceof COSNumber) {
            float tj = ((COSNumber) (obj)).floatValue();
            // calculate the combined displacements
            float tx;
            float ty;
            if (isVertical) {
                tx = 0;
                ty = ((-tj) / 1000) * fontSize;
            } else {
                tx = (((-tj) / 1000) * fontSize) * horizontalScaling;
                ty = 0;
            }
            applyTextAdjustment(tx, ty);
        } else if (obj instanceof COSString) {
            byte[] string = ((COSString) (obj)).getBytes();
            showText(string);
        } else if (obj instanceof COSArray) {
            LOG.error("Nested arrays are not allowed in an array for TJ operation: " + obj);
        } else {
            LOG.error((("Unknown type " + obj.getClass().getSimpleName()) + " in array for TJ operation: ") + obj);
        }
    }
}

