/**
 * Search for/parse the object with the given object number. The stream is closed after parsing the object with the
 * given number.
 *
 * @param objectNumber
 * 		the number of the object to b e parsed
 * @return the parsed object or null if the object with the given number can't be found
 * @throws IOException
 * 		if there is an error while parsing the stream
 */
public COSBase parseObject(long objectNumber) throws IOException {
    COSBase streamObject = null;
    try {
        Integer objectOffset = privateReadObjectNumbers().get(objectNumber);
        if (objectOffset != null) {
            // jump to the offset of the first object
            long currentPosition = source.getPosition();
            if ((firstObject > 0) && (currentPosition < firstObject)) {
                source.skip(firstObject - ((int) (currentPosition)));
            }
            // jump to the offset of the object to be parsed
            source.skip(objectOffset);
            // PATH: Test should invoke the next BaseParser.parseDirObject(...) [step in execution path]
            streamObject = parseDirObject();
            if (streamObject != null) {
                streamObject.setDirect(false);
            }
        }
    } finally {
        source.close();
        document = null;
    }
    return streamObject;
}

/**
 * This will parse a directory object from the stream.
 *
 * @return The parsed object.
 * @throws IOException
 * 		If there is an error during parsing.
 */
protected COSBase parseDirObject() throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        skipSpaces();
        char c = ((char) (source.peek()));
        switch (c) {
            case '<' :
                // pull off first left bracket
                source.read();
                // check for second left bracket
                c = ((char) (source.peek()));
                source.rewind(1);
                // PATH: Test should invoke the next BaseParser.parseCOSDictionary(...) [step in execution path]
                return c == '<' ? parseCOSDictionary(true) : parseCOSString();
            case '[' :
                // array
                return parseCOSArray();
            case '(' :
                return parseCOSString();
            case '/' :
                // name
                return parseCOSName();
            case 'n' :
                // null
                readExpectedString(NULL, false);
                return COSNull.NULL;
            case 't' :
                readExpectedString(TRUE, false);
                return COSBoolean.TRUE;
            case 'f' :
                readExpectedString(FALSE, false);
                return COSBoolean.FALSE;
            case 'R' :
                source.read();
                return new COSObject(null);
            case ((char) (-1)) :
                return null;
            default :
                if (((Character.isDigit(c) || (c == '-')) || (c == '+')) || (c == '.')) {
                    return parseCOSNumber();
                }
                // This is not suppose to happen, but we will allow for it
                // so we are more compatible with POS writers that don't
                // follow the spec
                long startOffset = source.getPosition();
                String badString = readString();
                if (badString.isEmpty()) {
                    int peek = source.peek();
                    // we can end up in an infinite loop otherwise
                    throw new IOException(((((((((((("Unknown dir object c='" + c) + "' cInt=") + ((int) (c))) + " peek='") + ((char) (peek))) + "' peekInt=") + peek) + " at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                }
                // if it's an endstream/endobj, we want to put it back so the caller will see it
                if (ENDOBJ_STRING.equals(badString) || ENDSTREAM_STRING.equals(badString)) {
                    source.rewind(badString.getBytes(StandardCharsets.ISO_8859_1).length);
                } else {
                    LOG.warn(((((("Skipped unexpected dir object = '" + badString) + "' at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                    return this instanceof PDFStreamParser ? null : COSNull.NULL;
                }
        }
        return null;
    } finally {
        recursionDepth--;
    }
}

/**
 * This will parse a PDF dictionary.
 *
 * @param isDirect
 * 		indicates whether the dictionary to be read is a direct object
 * @return The parsed dictionary, never null.
 * @throws IOException
 * 		If there is an error reading the stream.
 */
protected COSDictionary parseCOSDictionary(boolean isDirect) throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        readExpectedChar('<');
        readExpectedChar('<');
        skipSpaces();
        COSDictionary obj = new COSDictionary();
        obj.setDirect(isDirect);
        while (true) {
            skipSpaces();
            char c = ((char) (source.peek()));
            if (c == '>') {
                break;
            } else if (c == '/') {
                // something went wrong, most likely the dictionary is corrupted
                // stop immediately and return everything read so far
                if (// PATH: Test should invoke the next BaseParser.parseCOSDictionaryNameValuePair(...) [step in execution path]
                !parseCOSDictionaryNameValuePair(obj)) {
                    return obj;
                }
            } else {
                // invalid dictionary, we were expecting a /Name, read until the end or until we can recover
                LOG.warn((("Invalid dictionary, found: '" + c) + "' but expected: '/' at offset ") + source.getPosition());
                if (readUntilEndOfCOSDictionary()) {
                    // we couldn't recover
                    return obj;
                }
            }
        } 
        try {
            readExpectedChar('>');
            readExpectedChar('>');
        } catch (IOException exception) {
            LOG.warn("Invalid dictionary, can't find end of dictionary at offset " + source.getPosition());
        }
        return obj;
    } finally {
        recursionDepth--;
    }
}

private boolean parseCOSDictionaryNameValuePair(COSDictionary obj) throws IOException {
    COSName key = parseCOSName();
    if ((key == null) || key.getName().isEmpty()) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn("Empty COSName at offset " + source.getPosition());
    }
    COSBase value = parseCOSDictionaryValue();
    skipSpaces();
    if (value == null) {
        LOG.warn("Bad dictionary declaration at offset " + source.getPosition());
        return false;
    } else if ((value instanceof COSInteger) && (!((COSInteger) (value)).isValid())) {
        LOG.warn("Skipped out of range number value at offset " + source.getPosition());
    } else {
        // label this item as direct, to avoid signature problems.
        value.setDirect(true);
        obj.setItem(key, value);
    }
    return true;
}

