/**
 * This will parse the stream and populate the PDDocument object. This will close the keystore stream when it is
 * done parsing.
 *
 * @param lenient
 * 		activate leniency if set to true
 * @return the populated PDDocument
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public PDDocument parse(boolean lenient) throws IOException {
    setLenient(lenient);
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try {
        // PDFBOX-1922 read the version header and rewind
        if ((!parsePDFHeader()) && (!parseFDFHeader())) {
            if (lenient) {
                LOG.warn("Error: Header doesn't contain versioninfo");
            } else {
                throw new IOException("Error: Header doesn't contain versioninfo");
            }
        }
        if (!initialParseDone) // PATH: Test should invoke the next PDFParser.initialParse(...) [step in execution path]
        {
            initialParse();
        }
        exceptionOccurred = false;
        PDDocument pdDocument = createDocument();
        pdDocument.setEncryptionDictionary(getEncryption());
        return pdDocument;
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * The initial parse will first parse only the trailer, the xrefstart and all xref tables to have a pointer (offset)
 * to all the pdf's objects. It can handle linearized pdfs, which will have an xref at the end pointing to an xref
 * at the beginning of the file. Last the root object is parsed.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If something went wrong.
 */
protected void initialParse() throws IOException {
    // PATH: Test should invoke the next COSParser.retrieveTrailer(...) [step in execution path]
    COSDictionary trailer = retrieveTrailer();
    COSDictionary root = trailer.getCOSDictionary(COSName.ROOT);
    if (root == null) {
        throw new IOException("Missing root object specification in trailer.");
    }
    // in some pdfs the type value "Catalog" is missing in the root object
    if (isLenient() && (!root.containsKey(COSName.TYPE))) {
        root.setItem(COSName.TYPE, COSName.CATALOG);
    }
    // check pages dictionaries
    checkPages(root);
    document.setDecrypted();
    initialParseDone = true;
}

/**
 * Read the trailer information and provide a COSDictionary containing the trailer information.
 *
 * @return a COSDictionary containing the trailer information
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary retrieveTrailer() throws IOException {
    COSDictionary trailer = null;
    boolean rebuildTrailer = false;
    try {
        // parse startxref
        // TODO FDF files don't have a startxref value, so that rebuildTrailer is triggered
        long startXRefOffset = getStartxrefOffset();
        if (startXRefOffset > (-1)) {
            trailer = parseXref(startXRefOffset);
        } else {
            rebuildTrailer = isLenient();
        }
    } catch (IOException exception) {
        if (isLenient()) {
            rebuildTrailer = true;
        } else {
            throw exception;
        }
    }
    // check if the trailer contains a Root object
    if ((trailer != null) && (trailer.getItem(COSName.ROOT) == null)) {
        rebuildTrailer = isLenient();
    }
    if (rebuildTrailer) {
        trailer = getBruteForceParser().rebuildTrailer(xrefTrailerResolver, null);
        trailerWasRebuild = true;
        // transfer encryption information from BruteForceParser
        encryption = getBruteForceParser().getEncryption();
        if (encryption != null) {
            securityHandler = encryption.getSecurityHandler();
            accessPermission = securityHandler.getCurrentAccessPermission();
        }
    } else {
        // prepare decryption if necessary
        prepareDecryption();
        // don't use the getter as it creates an instance of BruteForceParser
        if ((bruteForceParser != null) && bruteForceParser.bfSearchTriggered()) // PATH: Test should invoke the next BruteForceParser.bfSearchForObjStreams(...) [step in execution path]
        {
            getBruteForceParser().bfSearchForObjStreams(xrefTrailerResolver, securityHandler);
        }
    }
    if (resetTrailerResolver()) {
        xrefTrailerResolver.reset();
        xrefTrailerResolver = null;
    }
    return trailer;
}

/**
 * Brute force search for all objects streams of a pdf.
 *
 * @param trailerResolver
 * 		the trailer resolver of the document
 * @param securityHandler
 * 		security handler to be used to decrypt encrypted documents
 * @throws IOException
 * 		if something went wrong
 */
protected void bfSearchForObjStreams(XrefTrailerResolver trailerResolver, SecurityHandler<? extends ProtectionPolicy> securityHandler) throws IOException {
    // update security handler
    this.securityHandler = securityHandler;
    // save origin offset
    long originOffset = source.getPosition();
    Map<Long, COSObjectKey> bfSearchForObjStreamOffsets = bfSearchForObjStreamOffsets();
    Map<COSObjectKey, Long> bfCOSObjectOffsets = getBFCOSObjectOffsets();
    // log warning about skipped stream
    // 
    // 
    bfSearchForObjStreamOffsets.entrySet().stream().filter(o -> bfCOSObjectOffsets.get(o.getValue()) == null).forEach(o -> LOG.warn((("Skipped incomplete object stream:" + o.getValue()) + " at ") + o.getKey()));
    // collect all stream offsets
    List<Long> objStreamOffsets = // 
    // 
    // 
    // 
    bfSearchForObjStreamOffsets.entrySet().stream().filter(o -> bfCOSObjectOffsets.get(o.getValue()) != null).filter(o -> o.getKey().equals(bfCOSObjectOffsets.get(o.getValue()))).map(Map.Entry::getKey).collect(Collectors.toList());
    // add all found compressed objects to the brute force search result
    for (Long offset : objStreamOffsets) {
        source.seek(offset);
        long stmObjNumber = readObjectNumber();
        int stmGenNumber = readGenerationNumber();
        readExpectedString(OBJ_MARKER, true);
        COSStream stream = null;
        try {
            COSDictionary dict = parseCOSDictionary(false);
            stream = parseCOSStream(dict);
            if (securityHandler != null) {
                securityHandler.decryptStream(stream, stmObjNumber, stmGenNumber);
            }
            PDFObjectStreamParser objStreamParser = new PDFObjectStreamParser(stream, document);
            Map<Long, Integer> objectNumbers = objStreamParser.readObjectNumbers();
            Map<COSObjectKey, Long> xrefOffset = trailerResolver.getXrefTable();
            for (Long objNumber : objectNumbers.keySet()) {
                COSObjectKey objKey = new COSObjectKey(objNumber, 0);
                Long existingOffset = bfCOSObjectOffsets.get(objKey);
                if ((existingOffset != null) && (existingOffset < 0)) {
                    // translate stream object key to its offset
                    COSObjectKey objStmKey = new COSObjectKey(Math.abs(existingOffset), 0);
                    existingOffset = bfCOSObjectOffsets.get(objStmKey);
                }
                if ((existingOffset == null) || (offset > existingOffset)) {
                    bfCOSObjectOffsets.put(objKey, -stmObjNumber);
                    xrefOffset.put(objKey, -stmObjNumber);
                }
            }
        } catch (IOException exception) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            LOG.debug((("Skipped corrupt stream: (" + stmObjNumber) + " 0 at offset ") + offset, exception);
        } finally {
            if (stream != null) {
                stream.close();
            }
        }
    }
    // restore origin offset
    source.seek(originOffset);
}

