@Override
public void showTransparencyGroup(PDTransparencyGroup form) throws IOException // PATH: Test should invoke the next PageDrawer.showTransparencyGroupOnGraphics(...) [step in execution path]
{
    showTransparencyGroupOnGraphics(form, graphics);
}

/**
 * For advanced users, to extract the transparency group into a separate graphics device.
 *
 * @param form
 * 		the transparency group to be extracted
 * @param graphics
 * 		the target graphics device
 * @throws IOException
 * 		if the transparency group could not be extracted
 */
protected void showTransparencyGroupOnGraphics(PDTransparencyGroup form, Graphics2D graphics) throws IOException {
    if (isHiddenOCG(form.getOptionalContent())) {
        return;
    }
    if (!isContentRendered()) {
        return;
    }
    TransparencyGroup group = new TransparencyGroup(form, false, getGraphicsState().getCurrentTransformationMatrix(), null);
    // PATH: Test should invoke the next new PageDrawer$TransparencyGroup(...) [step in execution path]
    BufferedImage image = group.getImage();
    if (image == null) {
        // image is empty, don't bother
        return;
    }
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    setClip();
    // both the DPI xform and the CTM were already applied to the group, so all we do
    // here is draw it directly onto the Graphics2D device at the appropriate position
    AffineTransform savedTransform = graphics.getTransform();
    AffineTransform transform = new AffineTransform(xform);
    transform.scale(1.0 / xformScalingFactorX, 1.0 / xformScalingFactorY);
    graphics.setTransform(transform);
    // adjust bbox (x,y) position at the initial scale + cropbox
    PDRectangle bbox = group.getBBox();
    float x = bbox.getLowerLeftX() - pageSize.getLowerLeftX();
    float y = pageSize.getUpperRightY() - bbox.getUpperRightY();
    if (flipTG) {
        graphics.translate(0, image.getHeight());
        graphics.scale(1, -1);
    } else {
        graphics.translate(x * xformScalingFactorX, y * xformScalingFactorY);
    }
    PDSoftMask softMask = getGraphicsState().getSoftMask();
    if (softMask != null) {
        Paint awtPaint = new TexturePaint(image, new Rectangle2D.Float(0, 0, image.getWidth(), image.getHeight()));
        awtPaint = applySoftMaskToPaint(awtPaint, softMask);
        graphics.setPaint(awtPaint);
        graphics.fill(new Rectangle2D.Float(0, 0, bbox.getWidth() * xformScalingFactorX, bbox.getHeight() * xformScalingFactorY));
    } else {
        try {
            graphics.drawImage(image, null, null);
        } catch (InternalError ie) {
            LOG.error("Exception drawing image, see JDK-6689349, " + "try rendering into a BufferedImage instead", ie);
        }
    }
    graphics.setTransform(savedTransform);
}

/**
 * Creates a buffered image for a transparency group result.
 *
 * @param form
 * 		the transparency group of the form or soft mask.
 * @param isSoftMask
 * 		true if this is a soft mask.
 * @param ctm
 * 		the relevant current transformation matrix. For soft masks, this is the CTM at
 * 		the time the soft mask is set (not at the time the soft mask is used for fill/stroke!),
 * 		for forms, this is the CTM at the time the form is invoked.
 * @param backdropColor
 * 		the color according to the /bc entry to be used for luminosity soft
 * 		masks.
 * @throws IOException
 */
private (PDTransparencyGroup form, boolean isSoftMask, Matrix ctm, PDColor backdropColor) throws IOException {
    Graphics2D savedGraphics = graphics;
    List<Path2D> savedLastClips = lastClips;
    Shape savedInitialClip = initialClip;
    // get the CTM x Form Matrix transform
    Matrix transform = Matrix.concatenate(ctm, form.getMatrix());
    // transform the bbox
    PDRectangle formBBox = form.getBBox();
    if (formBBox == null) {
        // PDFBOX-5471
        // check done here and not in caller to avoid getBBox() creating rectangle twice
        LOG.warn("transparency group ignored because BBox is null");
        formBBox = new PDRectangle();
    }
    GeneralPath transformedBox = formBBox.transform(transform);
    // clip the bbox to prevent giant bboxes from consuming all memory
    Area transformed = new Area(transformedBox);
    transformed.intersect(getGraphicsState().getCurrentClippingPath());
    Rectangle2D clipRect = transformed.getBounds2D();
    if (clipRect.isEmpty()) {
        image = null;
        bbox = null;
