/**
 * For advanced users, to extract the transparency group into a separate graphics device.
 *
 * @param form
 * 		the transparency group to be extracted
 * @param graphics
 * 		the target graphics device
 * @throws IOException
 * 		if the transparency group could not be extracted
 */
protected void showTransparencyGroupOnGraphics(PDTransparencyGroup form, Graphics2D graphics) throws IOException {
    if (isHiddenOCG(form.getOptionalContent())) {
        return;
    }
    if (!isContentRendered()) {
        return;
    }
    TransparencyGroup group = new TransparencyGroup(form, false, getGraphicsState().getCurrentTransformationMatrix(), null);
    BufferedImage image = group.getImage();
    if (image == null) {
        // image is empty, don't bother
        return;
    }
    graphics.setComposite(getGraphicsState().getNonStrokingJavaComposite());
    setClip();
    // both the DPI xform and the CTM were already applied to the group, so all we do
    // here is draw it directly onto the Graphics2D device at the appropriate position
    AffineTransform savedTransform = graphics.getTransform();
    AffineTransform transform = new AffineTransform(xform);
    transform.scale(1.0 / xformScalingFactorX, 1.0 / xformScalingFactorY);
    graphics.setTransform(transform);
    // adjust bbox (x,y) position at the initial scale + cropbox
    PDRectangle bbox = group.getBBox();
    float x = bbox.getLowerLeftX() - pageSize.getLowerLeftX();
    float y = pageSize.getUpperRightY() - bbox.getUpperRightY();
    if (flipTG) {
        graphics.translate(0, image.getHeight());
        graphics.scale(1, -1);
    } else {
        graphics.translate(x * xformScalingFactorX, y * xformScalingFactorY);
    }
    PDSoftMask softMask = getGraphicsState().getSoftMask();
    if (softMask != null) {
        Paint awtPaint = new TexturePaint(image, new Rectangle2D.Float(0, 0, image.getWidth(), image.getHeight()));
        awtPaint = applySoftMaskToPaint(awtPaint, softMask);
        graphics.setPaint(awtPaint);
        graphics.fill(new Rectangle2D.Float(0, 0, bbox.getWidth() * xformScalingFactorX, bbox.getHeight() * xformScalingFactorY));
    } else {
        try {
            graphics.drawImage(image, null, null);
        } catch (InternalError ie) {
            LOG.error("Exception drawing image, see JDK-6689349, " + "try rendering into a BufferedImage instead", ie);
        }
    }
    graphics.setTransform(savedTransform);
}

@Override
