/**
 * This will parse the next token in the stream.
 *
 * @return The next token in the stream or null if there are no more tokens in the stream.
 * @throws IOException
 * 		If an io error occurs while parsing the stream.
 */
public Object parseNextToken() throws IOException {
    if (source.isClosed()) {
        return null;
    }
    skipSpaces();
    if (source.isEOF()) {
        close();
        return null;
    }
    char c = ((char) (source.peek()));
    switch (c) {
        case '<' :
            // pull off first left bracket
            source.read();
            // check for second left bracket
            c = ((char) (source.peek()));
            // put back first bracket
            source.rewind(1);
            if (c == '<') {
                try {
                    // PATH: Test should invoke the next BaseParser.parseCOSDictionary(...) [step in execution path]
                    return parseCOSDictionary(true);
                } catch (IOException exception) {
                    LOG.warn("Stop reading invalid dictionary from content stream at offset " + source.getPosition());
                    close();
                    return null;
                }
            } else {
                return parseCOSString();
            }
        case '[' :
            // array
            try {
                return parseCOSArray();
            } catch (IOException exception) {
                LOG.warn("Stop reading invalid array from content stream at offset " + source.getPosition());
                close();
                return null;
            }
        case '(' :
            // string
            return parseCOSString();
        case '/' :
            // name
            return parseCOSName();
        case 'n' :
            // null
            String nullString = readString();
            if (nullString.equals("null")) {
                return COSNull.NULL;
            } else {
                return Operator.getOperator(nullString);
            }
        case 't' :
        case 'f' :
            String next = readString();
            if (next.equals("true")) {
                return COSBoolean.TRUE;
            } else if (next.equals("false")) {
                return COSBoolean.FALSE;
            } else {
                return Operator.getOperator(next);
            }
        case '0' :
        case '1' :
        case '2' :
        case '3' :
        case '4' :
        case '5' :
        case '6' :
        case '7' :
        case '8' :
        case '9' :
        case '-' :
        case '+' :
        case '.' :
            /* We will be filling buf with the rest of the number.  Only
            allow 1 "." and "-" and "+" at start of number.
             */
            StringBuilder buf = new StringBuilder();
            buf.append(c);
            source.read();
            // Ignore double negative (this is consistent with Adobe Reader)
            if ((c == '-') && (source.peek() == c)) {
                source.read();
            }
            boolean dotNotRead = c != '.';
            while ((Character.isDigit(c = ((char) (source.peek()))) || (dotNotRead && (c == '.'))) || (c == '-')) {
                if (c != '-') {
                    // PDFBOX-4064: ignore "-" in the middle of a number
                    buf.append(c);
                }
                source.read();
                if (dotNotRead && (c == '.')) {
                    dotNotRead = false;
                }
            } 
            String s = buf.toString();
            if ("+".equals(s)) {
                // PDFBOX-5906
                LOG.warn("isolated '+' is ignored");
                return COSNull.NULL;
            }
            return COSNumber.get(s);
        case 'B' :
            String nextOperator = readString();
            Operator beginImageOP = Operator.getOperator(nextOperator);
            if (nextOperator.equals(OperatorName.BEGIN_INLINE_IMAGE)) {
                inlineImageDepth++;
                if (inlineImageDepth > 1) {
                    // PDFBOX-6038
                    throw new IOException((((("Nested '" + OperatorName.BEGIN_INLINE_IMAGE) + "' operator not allowed at offset ") + source.getPosition()) + ", first: ") + inlineOffset);
                } else {
                    inlineOffset = source.getPosition();
                }
                COSDictionary imageParams = new COSDictionary();
                beginImageOP.setImageParameters(imageParams);
                Object nextToken = null;
                while ((nextToken = parseNextToken()) instanceof COSName) {
                    Object value = parseNextToken();
                    if (!(value instanceof COSBase)) {
                        LOG.warn("Unexpected token in inline image dictionary at offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                        break;
                    }
                    imageParams.setItem(((COSName) (nextToken)), ((COSBase) (value)));
                } 
                // final token will be the image data, maybe??
                if (nextToken instanceof Operator) {
                    Operator imageData = ((Operator) (nextToken));
                    if ((imageData.getImageData() == null) || (imageData.getImageData().length == 0)) {
                        LOG.warn("empty inline image at stream offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                    }
                    beginImageOP.setImageData(imageData.getImageData());
                    inlineImageDepth--;
                } else {
                    LOG.warn(((((("nextToken " + nextToken) + " at position ") + (source.isClosed() ? "EOF" : source.getPosition())) + ", expected ") + OperatorName.BEGIN_INLINE_IMAGE_DATA) + "?!");
                }
            }
            return beginImageOP;
        case 'I' :
            // Special case for ID operator
            String id = Character.toString(((char) (source.read()))) + ((char) (source.read()));
            if (!id.equals(OperatorName.BEGIN_INLINE_IMAGE_DATA)) {
                long currentPosition = source.getPosition();
                close();
                throw new IOException((("Error: Expected operator 'ID' actual='" + id) + "' at stream offset ") + currentPosition);
            }
            ByteArrayOutputStream imageData = new ByteArrayOutputStream();
            // skip one line break (CR, LF or CRLF) or any one-byte whitespace
            if ((!skipLinebreak()) && isWhitespace()) {
                // pull off the whitespace character
                source.read();
            }
            int lastByte = source.read();
            int currentByte = source.read();
            // PDF spec is kinda unclear about this. Should a whitespace
            // always appear before EI? Not sure, so that we just read
            // until EI<whitespace>.
            // Be aware not all kind of whitespaces are allowed here. see PDFBOX-1561
            while ((!((((lastByte == 'E') && (currentByte == 'I')) && hasNextSpaceOrReturn()) && hasNoFollowingBinData())) && (!isEOF())) {
                imageData.write(lastByte);
                lastByte = currentByte;
                currentByte = source.read();
            } 
            // the EI operator isn't unread, as it won't be processed anyway
            Operator beginImageDataOP = Operator.getOperator(OperatorName.BEGIN_INLINE_IMAGE_DATA);
            // save the image data to the operator, so that it can be accessed later
            beginImageDataOP.setImageData(imageData.toByteArray());
            return beginImageDataOP;
        case ']' :
            // some ']' around without its previous '['
            // this means a PDF is somewhat corrupt but we will continue to parse.
            source.read();
            // must be a better solution than null...
            return COSNull.NULL;
        default :
            // we must be an operator
            String operator = readOperator().trim();
            if (operator.length() > 0) {
                return Operator.getOperator(operator);
            }
    }
    return null;
}

/**
 * This will parse a PDF dictionary.
 *
 * @param isDirect
 * 		indicates whether the dictionary to be read is a direct object
 * @return The parsed dictionary, never null.
 * @throws IOException
 * 		If there is an error reading the stream.
 */
protected COSDictionary parseCOSDictionary(boolean isDirect) throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        readExpectedChar('<');
        readExpectedChar('<');
        skipSpaces();
        COSDictionary obj = new COSDictionary();
        obj.setDirect(isDirect);
        while (true) {
            skipSpaces();
            char c = ((char) (source.peek()));
            if (c == '>') {
                break;
            } else if (c == '/') {
                // something went wrong, most likely the dictionary is corrupted
                // stop immediately and return everything read so far
                if (// PATH: Test should invoke the next BaseParser.parseCOSDictionaryNameValuePair(...) [step in execution path]
                !parseCOSDictionaryNameValuePair(obj)) {
                    return obj;
                }
            } else {
                // invalid dictionary, we were expecting a /Name, read until the end or until we can recover
                LOG.warn((("Invalid dictionary, found: '" + c) + "' but expected: '/' at offset ") + source.getPosition());
                if (readUntilEndOfCOSDictionary()) {
                    // we couldn't recover
                    return obj;
                }
            }
        } 
        try {
            readExpectedChar('>');
            readExpectedChar('>');
        } catch (IOException exception) {
            LOG.warn("Invalid dictionary, can't find end of dictionary at offset " + source.getPosition());
        }
        return obj;
    } finally {
        recursionDepth--;
    }
}

private boolean parseCOSDictionaryNameValuePair(COSDictionary obj) throws IOException {
    COSName key = parseCOSName();
    if ((key == null) || key.getName().isEmpty()) {
        LOG.warn("Empty COSName at offset " + source.getPosition());
    }
    // PATH: Test should invoke the next BaseParser.parseCOSDictionaryValue(...) [step in execution path]
    COSBase value = parseCOSDictionaryValue();
    skipSpaces();
    if (value == null) {
        LOG.warn("Bad dictionary declaration at offset " + source.getPosition());
        return false;
    } else if ((value instanceof COSInteger) && (!((COSInteger) (value)).isValid())) {
        LOG.warn("Skipped out of range number value at offset " + source.getPosition());
    } else {
        // label this item as direct, to avoid signature problems.
        value.setDirect(true);
        obj.setItem(key, value);
    }
    return true;
}

/**
 * This will parse a PDF dictionary value.
 *
 * @return The parsed Dictionary object.
 * @throws IOException
 * 		If there is an error parsing the dictionary object.
 */
private COSBase parseCOSDictionaryValue() throws IOException {
    long numOffset = source.getPosition();
    COSBase value = parseDirObject();
    skipSpaces();
    // proceed if the given object is a number and the following is a number as well
    if ((!(value instanceof COSNumber)) || (!isDigit())) {
        return value;
    }
    // read the remaining information of the object number
    long genOffset = source.getPosition();
    COSBase generationNumber = parseDirObject();
    skipSpaces();
    readExpectedChar('R');
    if (!(value instanceof COSInteger)) {
        LOG.error((("expected number, actual=" + value) + " at offset ") + numOffset);
        return COSNull.NULL;
    }
    if (!(generationNumber instanceof COSInteger)) {
        LOG.error((("expected number, actual=" + generationNumber) + " at offset ") + genOffset);
        return COSNull.NULL;
    }
    long objNumber = ((COSInteger) (value)).longValue();
    if (objNumber <= 0) // PATH: Test should invoke the next Log.warn(...) [step in execution path]
    {
        LOG.warn((("invalid object number value =" + objNumber) + " at offset ") + numOffset);
        return COSNull.NULL;
    }
    int genNumber = ((COSInteger) (generationNumber)).intValue();
    if (genNumber < 0) {
        LOG.error((("invalid generation number value =" + genNumber) + " at offset ") + numOffset);
        return COSNull.NULL;
    }
    // dereference the object
    return getObjectFromPool(getObjectKey(objNumber, genNumber));
}

