/**
 * This will parse the next token in the stream.
 *
 * @return The next token in the stream or null if there are no more tokens in the stream.
 * @throws IOException
 * 		If an io error occurs while parsing the stream.
 */
public Object parseNextToken() throws IOException {
    if (source.isClosed()) {
        return null;
    }
    skipSpaces();
    if (source.isEOF()) {
        close();
        return null;
    }
    char c = ((char) (source.peek()));
    switch (c) {
        case '<' :
            // pull off first left bracket
            source.read();
            // check for second left bracket
            c = ((char) (source.peek()));
            // put back first bracket
            source.rewind(1);
            if (c == '<') {
                try {
                    return parseCOSDictionary(true);
                } catch (IOException exception) {
                    LOG.warn("Stop reading invalid dictionary from content stream at offset " + source.getPosition());
                    close();
                    return null;
                }
            } else {
                return parseCOSString();
            }
        case '[' :
            // array
            try {
                // PATH: Test should invoke the next BaseParser.parseCOSArray(...) [step in execution path]
                return parseCOSArray();
            } catch (IOException exception) {
                LOG.warn("Stop reading invalid array from content stream at offset " + source.getPosition());
                close();
                return null;
            }
        case '(' :
            // string
            return parseCOSString();
        case '/' :
            // name
            return parseCOSName();
        case 'n' :
            // null
            String nullString = readString();
            if (nullString.equals("null")) {
                return COSNull.NULL;
            } else {
                return Operator.getOperator(nullString);
            }
        case 't' :
        case 'f' :
            String next = readString();
            if (next.equals("true")) {
                return COSBoolean.TRUE;
            } else if (next.equals("false")) {
                return COSBoolean.FALSE;
            } else {
                return Operator.getOperator(next);
            }
        case '0' :
        case '1' :
        case '2' :
        case '3' :
        case '4' :
        case '5' :
        case '6' :
        case '7' :
        case '8' :
        case '9' :
        case '-' :
        case '+' :
        case '.' :
            /* We will be filling buf with the rest of the number.  Only
            allow 1 "." and "-" and "+" at start of number.
             */
            StringBuilder buf = new StringBuilder();
            buf.append(c);
            source.read();
            // Ignore double negative (this is consistent with Adobe Reader)
            if ((c == '-') && (source.peek() == c)) {
                source.read();
            }
            boolean dotNotRead = c != '.';
            while ((Character.isDigit(c = ((char) (source.peek()))) || (dotNotRead && (c == '.'))) || (c == '-')) {
                if (c != '-') {
                    // PDFBOX-4064: ignore "-" in the middle of a number
                    buf.append(c);
                }
                source.read();
                if (dotNotRead && (c == '.')) {
                    dotNotRead = false;
                }
            } 
            String s = buf.toString();
            if ("+".equals(s)) {
                // PDFBOX-5906
                LOG.warn("isolated '+' is ignored");
                return COSNull.NULL;
            }
            return COSNumber.get(s);
        case 'B' :
            String nextOperator = readString();
            Operator beginImageOP = Operator.getOperator(nextOperator);
            if (nextOperator.equals(OperatorName.BEGIN_INLINE_IMAGE)) {
                inlineImageDepth++;
                if (inlineImageDepth > 1) {
                    // PDFBOX-6038
                    throw new IOException((((("Nested '" + OperatorName.BEGIN_INLINE_IMAGE) + "' operator not allowed at offset ") + source.getPosition()) + ", first: ") + inlineOffset);
                } else {
                    inlineOffset = source.getPosition();
                }
                COSDictionary imageParams = new COSDictionary();
                beginImageOP.setImageParameters(imageParams);
                Object nextToken = null;
                while ((nextToken = parseNextToken()) instanceof COSName) {
                    Object value = parseNextToken();
                    if (!(value instanceof COSBase)) {
                        LOG.warn("Unexpected token in inline image dictionary at offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                        break;
                    }
                    imageParams.setItem(((COSName) (nextToken)), ((COSBase) (value)));
                } 
                // final token will be the image data, maybe??
                if (nextToken instanceof Operator) {
                    Operator imageData = ((Operator) (nextToken));
                    if ((imageData.getImageData() == null) || (imageData.getImageData().length == 0)) {
                        LOG.warn("empty inline image at stream offset " + (source.isClosed() ? "EOF" : source.getPosition()));
                    }
                    beginImageOP.setImageData(imageData.getImageData());
                    inlineImageDepth--;
                } else {
                    LOG.warn(((((("nextToken " + nextToken) + " at position ") + (source.isClosed() ? "EOF" : source.getPosition())) + ", expected ") + OperatorName.BEGIN_INLINE_IMAGE_DATA) + "?!");
                }
            }
            return beginImageOP;
        case 'I' :
            // Special case for ID operator
            String id = Character.toString(((char) (source.read()))) + ((char) (source.read()));
            if (!id.equals(OperatorName.BEGIN_INLINE_IMAGE_DATA)) {
                long currentPosition = source.getPosition();
                close();
                throw new IOException((("Error: Expected operator 'ID' actual='" + id) + "' at stream offset ") + currentPosition);
            }
            ByteArrayOutputStream imageData = new ByteArrayOutputStream();
            // skip one line break (CR, LF or CRLF) or any one-byte whitespace
            if ((!skipLinebreak()) && isWhitespace()) {
                // pull off the whitespace character
                source.read();
            }
            int lastByte = source.read();
            int currentByte = source.read();
            // PDF spec is kinda unclear about this. Should a whitespace
            // always appear before EI? Not sure, so that we just read
            // until EI<whitespace>.
            // Be aware not all kind of whitespaces are allowed here. see PDFBOX-1561
            while ((!((((lastByte == 'E') && (currentByte == 'I')) && hasNextSpaceOrReturn()) && hasNoFollowingBinData())) && (!isEOF())) {
                imageData.write(lastByte);
                lastByte = currentByte;
                currentByte = source.read();
            } 
            // the EI operator isn't unread, as it won't be processed anyway
            Operator beginImageDataOP = Operator.getOperator(OperatorName.BEGIN_INLINE_IMAGE_DATA);
            // save the image data to the operator, so that it can be accessed later
            beginImageDataOP.setImageData(imageData.toByteArray());
            return beginImageDataOP;
        case ']' :
            // some ']' around without its previous '['
            // this means a PDF is somewhat corrupt but we will continue to parse.
            source.read();
            // must be a better solution than null...
            return COSNull.NULL;
        default :
            // we must be an operator
            String operator = readOperator().trim();
            if (operator.length() > 0) {
                return Operator.getOperator(operator);
            }
    }
    return null;
}

/**
 * This will parse a PDF array object.
 *
 * @return The parsed PDF array.
 * @throws IOException
 * 		If there is an error parsing the stream.
 */
protected COSArray parseCOSArray() throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        long startPosition = source.getPosition();
        readExpectedChar('[');
        COSArray po = new COSArray();
        COSBase pbo;
        skipSpaces();
        int i;
        while (((i = source.peek()) > 0) && (((char) (i)) != ']')) {
            // PATH: Test should invoke the next BaseParser.parseDirObject(...) [step in execution path]
            pbo = parseDirObject();
            if (pbo instanceof COSObject) {
                // the current empty COSObject is replaced with the correct one
                pbo = null;
                // We have to check if the expected values are there or not PDFBOX-385
                if ((po.size() > 1) && (po.get(po.size() - 1) instanceof COSInteger)) {
                    COSInteger genNumber = ((COSInteger) (po.remove(po.size() - 1)));
                    if ((po.size() > 0) && (po.get(po.size() - 1) instanceof COSInteger)) {
                        COSInteger number = ((COSInteger) (po.remove(po.size() - 1)));
                        if ((number.longValue() >= 0) && (genNumber.intValue() >= 0)) {
                            COSObjectKey key = getObjectKey(number.longValue(), genNumber.intValue());
                            pbo = getObjectFromPool(key);
                        } else {
                            LOG.warn((("Invalid value(s) for an object key " + number.longValue()) + " ") + genNumber.intValue());
                        }
                    }
                }
            }
            // something went wrong
            if (pbo == null) {
                // it could be a bad object in the array which is just skipped
                LOG.warn((("Corrupt array element at offset " + source.getPosition()) + ", start offset: ") + startPosition);
                String isThisTheEnd = readString();
                // return immediately if a corrupt element is followed by another array
                // to avoid a possible infinite recursion as most likely the whole array is corrupted
                if (isThisTheEnd.isEmpty() && (source.peek() == '[')) {
                    return po;
                }
                source.rewind(isThisTheEnd.getBytes(StandardCharsets.ISO_8859_1).length);
                // This could also be an "endobj" or "endstream" which means we can assume that
                // the array has ended.
                if (ENDOBJ_STRING.equals(isThisTheEnd) || ENDSTREAM_STRING.equals(isThisTheEnd)) {
                    return po;
                }
            } else {
                po.add(pbo);
            }
            skipSpaces();
        } 
        // read ']'
        source.read();
        skipSpaces();
        return po;
    } finally {
        recursionDepth--;
    }
}

/**
 * This will parse a directory object from the stream.
 *
 * @return The parsed object.
 * @throws IOException
 * 		If there is an error during parsing.
 */
protected COSBase parseDirObject() throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        skipSpaces();
        char c = ((char) (source.peek()));
        switch (c) {
            case '<' :
                // pull off first left bracket
                source.read();
                // check for second left bracket
                c = ((char) (source.peek()));
                source.rewind(1);
                return c == '<' ? parseCOSDictionary(true) : parseCOSString();
            case '[' :
                // array
                return parseCOSArray();
            case '(' :
                return parseCOSString();
            case '/' :
                // name
                return parseCOSName();
            case 'n' :
                // null
                readExpectedString(NULL, false);
                return COSNull.NULL;
            case 't' :
                readExpectedString(TRUE, false);
                return COSBoolean.TRUE;
            case 'f' :
                readExpectedString(FALSE, false);
                return COSBoolean.FALSE;
            case 'R' :
                source.read();
                return new COSObject(null);
            case ((char) (-1)) :
                return null;
            default :
                if (((Character.isDigit(c) || (c == '-')) || (c == '+')) || (c == '.')) {
                    return parseCOSNumber();
                }
                // This is not suppose to happen, but we will allow for it
                // so we are more compatible with POS writers that don't
                // follow the spec
                long startOffset = source.getPosition();
                String badString = readString();
                if (badString.isEmpty()) {
                    int peek = source.peek();
                    // we can end up in an infinite loop otherwise
                    throw new IOException(((((((((((("Unknown dir object c='" + c) + "' cInt=") + ((int) (c))) + " peek='") + ((char) (peek))) + "' peekInt=") + peek) + " at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                }
                // if it's an endstream/endobj, we want to put it back so the caller will see it
                if (ENDOBJ_STRING.equals(badString) || ENDSTREAM_STRING.equals(badString)) {
                    source.rewind(badString.getBytes(StandardCharsets.ISO_8859_1).length);
                } else {
                    LOG.warn(((((("Skipped unexpected dir object = '" + badString) + "' at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                    return this instanceof PDFStreamParser ? null : COSNull.NULL;
                }
        }
        return null;
    } finally {
        recursionDepth--;
    }
}

