            } else if ((CmapTable.PLATFORM_MACINTOSH == cmap.getPlatformId()) && (CmapTable.ENCODING_MAC_ROMAN == cmap.getPlatformEncodingId())) {
                cmapMacRoman = cmap;
            } else if ((CmapTable.PLATFORM_UNICODE == cmap.getPlatformId()) && (CmapTable.ENCODING_UNICODE_1_0 == cmap.getPlatformEncodingId())) {
                // PDFBOX-4755 / PDF.js #5501
