private void enqueueKids(PDField node) {
    queue.add(node);
    set.add(node.getCOSObject());
    if (node instanceof PDNonTerminalField) {
        List<PDField> kids = ((PDNonTerminalField) (node)).getChildren();
        for (PDField kid : kids) {
