 */
protected long readLong() throws IOException // PATH: Test should invoke the next BaseParser.skipSpaces(...) [step in execution path]
{
    skipSpaces();
    long retval = 0;
    StringBuilder longBuffer = readStringNumber();
    try {
        retval = Long.parseLong(longBuffer.toString());
    } catch (NumberFormatException e) {
        source.rewind(longBuffer.toString().getBytes(StandardCharsets.ISO_8859_1).length);
        throw new IOException(((("Error: Expected a long type at offset " + source.getPosition()) + ", instead got '") + longBuffer) + "'", e);
    }
    return retval;
}

/**
 * This will skip all spaces and comments that are present.
 *
 * @throws IOException
 * 		If there is an error reading from the stream.
 */
protected void skipSpaces() throws IOException {
    int c = source.read();
    // 37 is the % character, a comment
    while (isWhitespace(c) || (c == 37)) {
        if (c == 37) {
            // skip past the comment section
            c = source.read();
            while ((!isEOL(c)) && (c != (-1))) {
                c = source.read();
            } 
        } else {
            c = source.read();
        }
    } 
    if (c != (-1)) {
        source.rewind(1);
    }
}

