/**
 * Returns a new OutputStream for writing stream data, using and the given filters.
 *
 * @param filters
 * 		COSArray or COSName of filters to be used.
 * @return OutputStream for un-encoded stream data.
 * @throws IOException
 * 		If the output stream could not be created.
 */
public OutputStream createOutputStream(COSBase filters) throws IOException {
    checkClosed();
    if (isWriting) {
        throw new IllegalStateException("Cannot have more than one open stream writer.");
    }
    // apply filters, if any
    if (filters != null) {
        setItem(COSName.FILTER, filters);
    }
    if (randomAccess != null) {
        randomAccess.clear();
    } else {
        randomAccess = getStreamCache().createBuffer();
    }
    OutputStream randomOut = new RandomAccessOutputStream(randomAccess);
    OutputStream cosOut = // PATH: Test should invoke the next COSStream.getFilterList(...) [step in execution path]
    new COSOutputStream(getFilterList(), this, randomOut, getStreamCache());
    isWriting = true;
    return new FilterOutputStream(cosOut) {
        @Override
        public void write(byte[] b, int off, int len) throws IOException {
            this.out.write(b, off, len);
        }

        @Override
        public void close() throws IOException {
            super.close();
            setInt(COSName.LENGTH, ((int) (randomAccess.length())));
            isWriting = false;
        }
    };
}

