@Override
public void showForm(PDFormXObject form) throws IOException {
    if (isHiddenOCG(form.getOptionalContent())) {
        return;
    }
    if (isContentRendered()) {
        GeneralPath savedLinePath = linePath;
        linePath = new GeneralPath();
        super.showForm(form);
