            }
            float len1 = ((float) (Math.sqrt(Math.pow(pathsArray[(i * 8) + 2] - pathsArray[(i * 8) + 6], 2) + Math.pow(pathsArray[(i * 8) + 3] - pathsArray[(i * 8) + 7], 2))));
            float x1 = pathsArray[(i * 8) + 6];
            float y1 = pathsArray[(i * 8) + 7];
