public void generateNormalAppearance() {
    PDAnnotationLink annotation = ((PDAnnotationLink) (getAnnotation()));
    PDRectangle rect = annotation.getRectangle();
    if (rect == null) {
        // 660402-p1-AnnotationEmptyRect.pdf has /Rect entry with 0 elements
        return;
    }
