    float lineWidth = getLineWidth();
    try (// PATH: Test should invoke the next PDAbstractAppearanceHandler.getNormalAppearanceAsContentStream(...) [step in execution path]
    PDAppearanceContentStream contentStream = getNormalAppearanceAsContentStream()) {
        PDColor color = annotation.getColor();
        if (color == null) {
            // spec is unclear, but black is what Adobe does
            color = new PDColor(new float[]{ 0 }, PDDeviceGray.INSTANCE);
        }
        boolean hasStroke = contentStream.setStrokingColorOnDemand(color);
        contentStream.setBorderLine(lineWidth, annotation.getBorderStyle(), annotation.getBorder());
        // Acrobat applies a padding to each side of the bbox so the line is completely within
        // the bbox.
