 * Private. Creates a new PDType0Font font for embedding.
 *
 * @param document
 * @param ttf
 * @param embedSubset
 * @param closeTTF
 * 		whether to close the ttf parameter after embedding. Must be true when the ttf
 * 		parameter was created in the load() method, false when the ttf parameter was passed to the
 * 		load() method.
 * @param vertical
 * 		whether to enable vertical substitutions.
 * @throws IOException
 */
private (PDDocument document, TrueTypeFont ttf, boolean embedSubset, boolean closeTTF, boolean vertical) throws IOException {
    if (vertical) {
        ttf.enableVerticalSubstitutions();
    }
    gsubData = ttf.getGsubData();
    cmapLookup = ttf.getUnicodeCmapLookup();
    embedder = new PDCIDFontType2Embedder(document, dict, ttf, embedSubset, this, vertical);
    // PATH: Test should invoke the next new PDCIDFontType2Embedder(...) [step in execution path]
    descendantFont = embedder.getCIDFont();
    readEncoding();
    fetchCMapUCS2();
    if (closeTTF) {
        if (embedSubset) {
            this.ttf = ttf;
            document.registerTrueTypeFontForClosing(ttf);
        } else {
            // the TTF is fully loaded and it is safe to close the underlying data source
            ttf.close();
        }
    }
}

/**
 * Creates a new TrueType font embedder for the given TTF as a PDCIDFontType2.
 *
 * @param document
 * 		parent document
 * @param dict
 * 		font dictionary
 * @param ttf
 * 		True Type Font
 * @param parent
 * 		parent Type 0 font
 * @throws IOException
 * 		if the TTF could not be read
 */
(PDDocument document, COSDictionary dict, TrueTypeFont ttf, boolean embedSubset, PDType0Font parent, boolean vertical) throws IOException {
    this(document, dict, ttf, embedSubset);
    this.document = document;
    this.dict = dict;
    this.parent = parent;
    this.vertical = vertical;
    // parent Type 0 font
    dict.setItem(COSName.SUBTYPE, COSName.TYPE0);
    dict.setName(COSName.BASE_FONT, fontDescriptor.getFontName());
    dict.setItem(COSName.ENCODING, vertical ? COSName.IDENTITY_V : COSName.IDENTITY_H);// CID = GID

    // descendant CIDFont
    cidFont = createCIDFont();
    COSArray descendantFonts = new COSArray();
    descendantFonts.add(cidFont);
    dict.setItem(COSName.DESCENDANT_FONTS, descendantFonts);
    if (!embedSubset) // PATH: Test should invoke the next PDCIDFontType2Embedder.buildToUnicodeCMap(...) [step in execution path]
    {
        // build GID -> Unicode map
        buildToUnicodeCMap(null);
    }
}

private void buildToUnicodeCMap(Map<Integer, Integer> newGIDToOldCID) throws IOException {
    ToUnicodeWriter toUniWriter = new ToUnicodeWriter();
    boolean hasSurrogates = false;
    for (int gid = 1, max = ttf.getMaximumProfile().getNumGlyphs(); gid <= max; gid++) {
        // optional CID2GIDMap for subsetting
        int cid;
        if (newGIDToOldCID != null) {
            if (!newGIDToOldCID.containsKey(gid)) {
                continue;
            } else {
                cid = newGIDToOldCID.get(gid);
            }
        } else {
            cid = gid;
        }
        // skip composite glyph components that have no code point
        List<Integer> codes = cmapLookup.getCharCodes(cid);// old GID -> Unicode

        if (codes != null) {
            // use the first entry even for ambiguous mappings
            int codePoint = codes.get(0);
            if (codePoint > 0xffff) {
                hasSurrogates = true;
            }
            toUniWriter.add(cid, new String(new int[]{ codePoint }, 0, 1));
        }
    }
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    toUniWriter.writeTo(out);
    InputStream cMapStream = new ByteArrayInputStream(out.toByteArray());
    PDStream stream = new PDStream(document, cMapStream, COSName.FLATE_DECODE);
    // surrogate code points, requires PDF 1.5
    if (hasSurrogates) {
        float version = document.getVersion();
        if (version < 1.5) {
            document.setVersion(1.5F);
        }
    }
    dict.setItem(COSName.TO_UNICODE, stream);
}

