                float xx2 = x2 - ((float) (y * Math.sin(angle)));
                float yy2 = y2 + ((float) (y * Math.cos(angle)));
                drawStyle(annotation.getEndPointEndingStyle(), cs, xx2, yy2, lineEndingSize, hasStroke, hasBackground, true);
            }
        }
    } catch (IOException ex) {
        LOG.error(ex);
    }
