/**
 * This will parse the stream and populate the PDDocument object. This will close the keystore stream when it is
 * done parsing.
 *
 * @param lenient
 * 		activate leniency if set to true
 * @return the populated PDDocument
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If there is an error reading from the stream or corrupt data is found.
 */
public PDDocument parse(boolean lenient) throws IOException {
    setLenient(lenient);
    // set to false if all is processed
    boolean exceptionOccurred = true;
    try {
        // PDFBOX-1922 read the version header and rewind
        if ((!parsePDFHeader()) && (!parseFDFHeader())) {
            if (lenient) {
                LOG.warn("Error: Header doesn't contain versioninfo");
            } else {
                throw new IOException("Error: Header doesn't contain versioninfo");
            }
        }
        if (!initialParseDone) // PATH: Test should invoke the next PDFParser.initialParse(...) [step in execution path]
        {
            initialParse();
        }
        exceptionOccurred = false;
        PDDocument pdDocument = createDocument();
        pdDocument.setEncryptionDictionary(getEncryption());
        return pdDocument;
    } finally {
        if (exceptionOccurred && (document != null)) {
            IOUtils.closeQuietly(document);
            document = null;
        }
    }
}

/**
 * The initial parse will first parse only the trailer, the xrefstart and all xref tables to have a pointer (offset)
 * to all the pdf's objects. It can handle linearized pdfs, which will have an xref at the end pointing to an xref
 * at the beginning of the file. Last the root object is parsed.
 *
 * @throws InvalidPasswordException
 * 		If the password is incorrect.
 * @throws IOException
 * 		If something went wrong.
 */
protected void initialParse() throws IOException {
    // PATH: Test should invoke the next COSParser.retrieveTrailer(...) [step in execution path]
    COSDictionary trailer = retrieveTrailer();
    COSDictionary root = trailer.getCOSDictionary(COSName.ROOT);
    if (root == null) {
        throw new IOException("Missing root object specification in trailer.");
    }
    // in some pdfs the type value "Catalog" is missing in the root object
    if (isLenient() && (!root.containsKey(COSName.TYPE))) {
        root.setItem(COSName.TYPE, COSName.CATALOG);
    }
    // check pages dictionaries
    checkPages(root);
    document.setDecrypted();
    initialParseDone = true;
}

/**
 * Read the trailer information and provide a COSDictionary containing the trailer information.
 *
 * @return a COSDictionary containing the trailer information
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary retrieveTrailer() throws IOException {
    COSDictionary trailer = null;
    boolean rebuildTrailer = false;
    try {
        // parse startxref
        // TODO FDF files don't have a startxref value, so that rebuildTrailer is triggered
        long startXRefOffset = getStartxrefOffset();
        if (startXRefOffset > (-1)) {
            trailer = parseXref(startXRefOffset);
        } else {
            rebuildTrailer = isLenient();
        }
    } catch (IOException exception) {
        if (isLenient()) {
            rebuildTrailer = true;
        } else {
            throw exception;
        }
    }
    // check if the trailer contains a Root object
    if ((trailer != null) && (trailer.getItem(COSName.ROOT) == null)) {
        rebuildTrailer = isLenient();
    }
    if (rebuildTrailer) {
        // PATH: Test should invoke the next BruteForceParser.rebuildTrailer(...) [step in execution path]
        trailer = getBruteForceParser().rebuildTrailer(xrefTrailerResolver, null);
        trailerWasRebuild = true;
        // transfer encryption information from BruteForceParser
        encryption = getBruteForceParser().getEncryption();
        if (encryption != null) {
            securityHandler = encryption.getSecurityHandler();
            accessPermission = securityHandler.getCurrentAccessPermission();
        }
    } else {
        // prepare decryption if necessary
        prepareDecryption();
        // don't use the getter as it creates an instance of BruteForceParser
        if ((bruteForceParser != null) && bruteForceParser.bfSearchTriggered()) {
            getBruteForceParser().bfSearchForObjStreams(xrefTrailerResolver, securityHandler);
        }
    }
    if (resetTrailerResolver()) {
        xrefTrailerResolver.reset();
        xrefTrailerResolver = null;
    }
    return trailer;
}

/**
 * Rebuild the trailer dictionary if startxref can't be found.
 *
 * @param trailerResolver
 * 		the trailer resolver of the document
 * @param securityHandler
 * 		security handler to be used to decrypt encrypted documents
 * @return the rebuild trailer dictionary
 * @throws IOException
 * 		if something went wrong
 */
protected COSDictionary rebuildTrailer(XrefTrailerResolver trailerResolver, SecurityHandler<? extends ProtectionPolicy> securityHandler) throws IOException {
    // update security handler
    this.securityHandler = securityHandler;
    // reset trailer resolver
    trailerResolver.reset();
    // use the found objects to rebuild the trailer resolver
    trailerResolver.nextXrefObj(0, XRefType.TABLE);
    getBFCOSObjectOffsets().forEach(trailerResolver::setXRef);
    trailerResolver.setStartxref(0);
    // transfer xref-table to document
    document.getXrefTable().clear();
    document.addXRefTable(trailerResolver.getXrefTable());
    // remember the highest XRef object number to avoid it being reused in incremental saving
    Long maxValue = // 
    // 
    // 
    document.getXrefTable().keySet().stream().map(COSObjectKey::getNumber).reduce(Long::max).orElse(0L);
    document.setHighestXRefObjectNumber(maxValue);
    COSDictionary trailer = trailerResolver.getTrailer();
    document.setTrailer(trailer);
    boolean searchForObjStreamsDone = false;
    if (// PATH: Test should invoke the next BruteForceParser.bfSearchForTrailer(...) [step in execution path]
    (!bfSearchForTrailer(trailer)) && (!searchForTrailerItems(trailer))) {
        // root entry wasn't found, maybe it is part of an object stream
        // brute force search for all object streams.
        bfSearchForObjStreams(trailerResolver, securityHandler);
        searchForObjStreamsDone = true;
        // search again for the root entry
        searchForTrailerItems(trailer);
    }
    // prepare decryption if necessary
    prepareDecryption();
    if (!searchForObjStreamsDone) {
        // brute force search for all object streams.
        bfSearchForObjStreams(trailerResolver, securityHandler);
    }
    return trailer;
}

/**
 * Brute force search for all trailer marker.
 *
 * @param trailer
 * 		dictionary to be used as trailer dictionary
 * @throws IOException
 * 		if something went wrong
 */
private boolean bfSearchForTrailer(COSDictionary trailer) throws IOException {
    long originOffset = source.getPosition();
    source.seek(MINIMUM_SEARCH_OFFSET);
    // search for trailer marker
    long trailerOffset = findString(TRAILER_MARKER);
    while (trailerOffset != (-1)) {
        try {
            boolean rootFound = false;
            boolean infoFound = false;
            skipSpaces();
            COSDictionary trailerDict = parseCOSDictionary(true);
            COSObject rootObj = trailerDict.getCOSObject(COSName.ROOT);
            if (rootObj != null) {
                // check if the dictionary can be dereferenced and is the one we are looking for
                COSBase rootDict = rootObj.getObject();
                if ((rootDict instanceof COSDictionary) && isCatalog(((COSDictionary) (rootDict)))) {
                    rootFound = true;
                }
            }
            COSObject infoObj = trailerDict.getCOSObject(COSName.INFO);
            if (infoObj != null) {
                // check if the dictionary can be dereferenced and is the one we are looking for
                COSBase infoDict = infoObj.getObject();
                if ((infoDict instanceof COSDictionary) && isInfo(((COSDictionary) (infoDict)))) {
                    infoFound = true;
                }
            }
            if (rootFound && infoFound) {
                trailer.setItem(COSName.ROOT, rootObj);
                trailer.setItem(COSName.INFO, infoObj);
                if (trailerDict.containsKey(COSName.ENCRYPT)) {
                    COSObject encObj = trailerDict.getCOSObject(COSName.ENCRYPT);
                    // check if the dictionary can be dereferenced
                    // TODO check if the dictionary is an encryption dictionary?
                    if ((encObj != null) && (encObj.getObject() instanceof COSDictionary)) {
                        trailer.setItem(COSName.ENCRYPT, encObj);
                    }
                }
                if (trailerDict.containsKey(COSName.ID)) {
                    COSBase idObj = trailerDict.getItem(COSName.ID);
                    if (idObj instanceof COSArray) {
                        trailer.setItem(COSName.ID, idObj);
                    }
                }
                return true;
            }
        } catch (IOException exception) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
        {
            LOG.debug("An exception occurred during brute force search for trailer - ignoring", exception);
        }
        trailerOffset = findString(TRAILER_MARKER);
    } 
    source.seek(originOffset);
    return false;
}

