@Override
public COSBase dereferenceCOSObject(COSObject obj) throws IOException {
    long currentPos = source.getPosition();
    COSObjectKey key = obj.getKey();
    // PATH: Test should invoke the next COSParser.parseObjectDynamically(...) [step in execution path]
    COSBase parsedObj = parseObjectDynamically(key, false);
    if (parsedObj != null) {
        parsedObj.setDirect(false);
        parsedObj.setKey(key);
    }
    if (currentPos > 0) {
        source.seek(currentPos);
    }
    return parsedObj;
}

/**
 * Parse the object for the given object key.
 *
 * @param objKey
 * 		key of object to be parsed
 * @param requireExistingNotCompressedObj
 * 		if <code>true</code> the object to be parsed must be defined in xref
 * 		(comment: null objects may be missing from xref) and it must not be a compressed object within object stream
 * 		(this is used to circumvent being stuck in a loop in a malicious PDF)
 * @return the parsed object (which is also added to document object)
 * @throws IOException
 * 		If an IO error occurs.
 */
protected synchronized COSBase parseObjectDynamically(COSObjectKey objKey, boolean requireExistingNotCompressedObj) throws IOException {
    COSObject pdfObject = document.getObjectFromPool(objKey);
    if (!pdfObject.isObjectNull()) {
        return pdfObject.getObject();
    }
    Long offsetOrObjstmObNr = getObjectOffset(objKey, requireExistingNotCompressedObj);
    COSBase referencedObject = null;
    if (offsetOrObjstmObNr != null) {
        if (offsetOrObjstmObNr > 0) {
            // PATH: Test should invoke the next COSParser.parseFileObject(...) [step in execution path]
            referencedObject = parseFileObject(offsetOrObjstmObNr, objKey);
        } else {
            // xref value is object nr of object stream containing object to be parsed
            // since our object was not found it means object stream was not parsed so far
            referencedObject = parseObjectStreamObject(-offsetOrObjstmObNr, objKey);
        }
    }
    if ((referencedObject == null) || (referencedObject instanceof COSNull)) {
        // not defined object -> NULL object (Spec. 1.7, chap. 3.2.9)
        // or some other issue with dereferencing
        // remove parser to avoid endless recursion
        pdfObject.setToNull();
    }
    return referencedObject;
}

private COSBase parseFileObject(Long objOffset, final COSObjectKey objKey) throws IOException {
    // jump to the object start
    source.seek(objOffset);
    // an indirect object starts with the object number/generation number
    final long readObjNr = readObjectNumber();
    final int readObjGen = readGenerationNumber();
    readExpectedString(OBJ_MARKER, true);
    // consistency check
    if ((readObjNr != objKey.getNumber()) || (readObjGen != objKey.getGeneration())) {
        throw new IOException((((((((("XREF for " + objKey.getNumber()) + ":") + objKey.getGeneration()) + " points to wrong object: ") + readObjNr) + ":") + readObjGen) + " at offset ") + objOffset);
    }
    skipSpaces();
    COSBase parsedObject = parseDirObject();
    if (parsedObject != null) {
        parsedObject.setDirect(false);
        parsedObject.setKey(objKey);
    }
    String endObjectKey = readString();
    if (endObjectKey.equals(STREAM_STRING)) {
        source.rewind(endObjectKey.getBytes(StandardCharsets.ISO_8859_1).length);
        if (parsedObject instanceof COSDictionary) {
            // PATH: Test should invoke the next COSParser.parseCOSStream(...) [step in execution path]
            COSStream stream = parseCOSStream(((COSDictionary) (parsedObject)));
            if (securityHandler != null) {
                securityHandler.decryptStream(stream, objKey.getNumber(), objKey.getGeneration());
            }
            parsedObject = stream;
        } else {
            // this is not legal
            // the combination of a dict and the stream/endstream
            // forms a complete stream object
            throw new IOException(("Stream not preceded by dictionary (offset: " + objOffset) + ").");
        }
        skipSpaces();
        endObjectKey = readLine();
        // we have case with a second 'endstream' before endobj
        if ((!endObjectKey.startsWith(ENDOBJ_STRING)) && endObjectKey.startsWith(ENDSTREAM_STRING)) {
            endObjectKey = endObjectKey.substring(9).trim();
            if (endObjectKey.length() == 0) {
                // no other characters in extra endstream line
                // read next line
                endObjectKey = readLine();
            }
        }
    } else if (securityHandler != null) {
        securityHandler.decrypt(parsedObject, objKey.getNumber(), objKey.getGeneration());
    }
    if (!endObjectKey.startsWith(ENDOBJ_STRING)) {
        if (isLenient) {
            LOG.warn(((((((("Object (" + readObjNr) + ":") + readObjGen) + ") at offset ") + objOffset) + " does not end with 'endobj' but with '") + endObjectKey) + "'");
        } else {
            throw new IOException(((((((("Object (" + readObjNr) + ":") + readObjGen) + ") at offset ") + objOffset) + " does not end with 'endobj' but with '") + endObjectKey) + "'");
        }
    }
    return parsedObject;
}

/**
 * This will read a COSStream from the input stream using length attribute within dictionary. If
 * length attribute is a indirect reference it is first resolved to get the stream length. This
 * means we copy stream data without testing for 'endstream' or 'endobj' and thus it is no
 * problem if these keywords occur within stream. We require 'endstream' to be found after
 * stream data is read.
 *
 * @param dic
 * 		dictionary that goes with this stream.
 * @return parsed pdf stream.
 * @throws IOException
 * 		if an error occurred reading the stream, like problems with reading
 * 		length attribute, stream does not end with 'endstream' after data read, stream too short etc.
 */
protected COSStream parseCOSStream(COSDictionary dic) throws IOException {
    // read 'stream'; this was already tested in parseObjectsDynamically()
    readString();
    skipWhiteSpaces();
    /* This needs to be dic.getItem because when we are parsing, the underlying object might still be null. */
    COSNumber streamLengthObj = getLength(dic.getItem(COSName.LENGTH));
    if (streamLengthObj == null) {
        if (isLenient) {
            LOG.warn("The stream doesn't provide any stream length, using fallback readUntilEnd, at offset " + source.getPosition());
        } else {
            throw new IOException("Missing length for stream.");
        }
    }
    long streamStartPosition = source.getPosition();
    long streamLength;
    // PATH: Test should invoke the next COSParser.validateStreamLength(...) [step in execution path]
    if ((streamLengthObj != null) && validateStreamLength(streamLengthObj.longValue())) {
        streamLength = streamLengthObj.longValue();
        // skip stream
        source.seek(source.getPosition() + streamLengthObj.intValue());
    } else {
        streamLength = readUntilEndStream(new EndstreamFilterStream());
        if ((streamLengthObj == null) || (streamLengthObj.longValue() != streamLength)) {
            dic.setLong(COSName.LENGTH, streamLength);
        }
    }
    String endStream = readString();
    if (endStream.equals("endobj") && isLenient) {
        LOG.warn("stream ends with 'endobj' instead of 'endstream' at offset " + source.getPosition());
        // avoid follow-up warning about missing endobj
        source.rewind(ENDOBJ.length);
    } else if (((endStream.length() > 9) && isLenient) && endStream.startsWith(ENDSTREAM_STRING)) {
        LOG.warn((("stream ends with '" + endStream) + "' instead of 'endstream' at offset ") + source.getPosition());
        // unread the "extra" bytes
        source.rewind(endStream.substring(9).getBytes(StandardCharsets.ISO_8859_1).length);
    } else if (!endStream.equals(ENDSTREAM_STRING)) {
        throw new IOException((("Error reading stream, expected='endstream' actual='" + endStream) + "' at offset ") + source.getPosition());
    }
    return document.createCOSStream(dic, streamStartPosition, streamLength);
}

private boolean validateStreamLength(long streamLength) throws IOException {
    long originOffset = source.getPosition();
    if (streamLength == 0) // PATH: Test should invoke the next Log.debug(...) [step in execution path]
    {
        // This may be valid (PDFBOX-5954), or not (PDFBOX-5880)
        LOG.debug("Suspicious stream length 0, stream position: " + originOffset);
        return false;
    } else if (streamLength < 0) {
        LOG.warn((("Invalid stream length: " + streamLength) + ", start position: ") + originOffset);
        return false;
    }
    long expectedEndOfStream = originOffset + streamLength;
    if (expectedEndOfStream > fileLen) {
        LOG.warn(((((("The end of the stream is out of range, using workaround to read the stream, " + "stream start position: ") + originOffset) + ", length: ") + streamLength) + ", expected end position: ") + expectedEndOfStream);
        return false;
    }
    source.seek(expectedEndOfStream);
    skipSpaces();
    boolean endStreamFound = isString(ENDSTREAM);
    source.seek(originOffset);
    if (!endStreamFound) {
        LOG.warn(((((("The end of the stream doesn't point to the correct offset, using workaround to read the stream, " + "stream start position: ") + originOffset) + ", length: ") + streamLength) + ", expected end position: ") + expectedEndOfStream);
        return false;
    }
    return true;
}

