@Override
public COSBase dereferenceCOSObject(COSObject obj) throws IOException {
    long currentPos = source.getPosition();
    COSObjectKey key = obj.getKey();
    // PATH: Test should invoke the next COSParser.parseObjectDynamically(...) [step in execution path]
    COSBase parsedObj = parseObjectDynamically(key, false);
    if (parsedObj != null) {
        parsedObj.setDirect(false);
        parsedObj.setKey(key);
    }
    if (currentPos > 0) {
        source.seek(currentPos);
    }
    return parsedObj;
}

/**
 * Parse the object for the given object key.
 *
 * @param objKey
 * 		key of object to be parsed
 * @param requireExistingNotCompressedObj
 * 		if <code>true</code> the object to be parsed must be defined in xref
 * 		(comment: null objects may be missing from xref) and it must not be a compressed object within object stream
 * 		(this is used to circumvent being stuck in a loop in a malicious PDF)
 * @return the parsed object (which is also added to document object)
 * @throws IOException
 * 		If an IO error occurs.
 */
protected synchronized COSBase parseObjectDynamically(COSObjectKey objKey, boolean requireExistingNotCompressedObj) throws IOException {
    COSObject pdfObject = document.getObjectFromPool(objKey);
    if (!pdfObject.isObjectNull()) {
        return pdfObject.getObject();
    }
    Long offsetOrObjstmObNr = getObjectOffset(objKey, requireExistingNotCompressedObj);
    COSBase referencedObject = null;
    if (offsetOrObjstmObNr != null) {
        if (offsetOrObjstmObNr > 0) {
            // PATH: Test should invoke the next COSParser.parseFileObject(...) [step in execution path]
            referencedObject = parseFileObject(offsetOrObjstmObNr, objKey);
        } else {
            // xref value is object nr of object stream containing object to be parsed
            // since our object was not found it means object stream was not parsed so far
            referencedObject = parseObjectStreamObject(-offsetOrObjstmObNr, objKey);
        }
    }
    if ((referencedObject == null) || (referencedObject instanceof COSNull)) {
        // not defined object -> NULL object (Spec. 1.7, chap. 3.2.9)
        // or some other issue with dereferencing
        // remove parser to avoid endless recursion
        pdfObject.setToNull();
    }
    return referencedObject;
}

private COSBase parseFileObject(Long objOffset, final COSObjectKey objKey) throws IOException {
    // jump to the object start
    source.seek(objOffset);
    // an indirect object starts with the object number/generation number
    final long readObjNr = readObjectNumber();
    final int readObjGen = readGenerationNumber();
    readExpectedString(OBJ_MARKER, true);
    // consistency check
    if ((readObjNr != objKey.getNumber()) || (readObjGen != objKey.getGeneration())) {
        throw new IOException((((((((("XREF for " + objKey.getNumber()) + ":") + objKey.getGeneration()) + " points to wrong object: ") + readObjNr) + ":") + readObjGen) + " at offset ") + objOffset);
    }
    skipSpaces();
    // PATH: Test should invoke the next BaseParser.parseDirObject(...) [step in execution path]
    COSBase parsedObject = parseDirObject();
    if (parsedObject != null) {
        parsedObject.setDirect(false);
        parsedObject.setKey(objKey);
    }
    String endObjectKey = readString();
    if (endObjectKey.equals(STREAM_STRING)) {
        source.rewind(endObjectKey.getBytes(StandardCharsets.ISO_8859_1).length);
        if (parsedObject instanceof COSDictionary) {
            COSStream stream = parseCOSStream(((COSDictionary) (parsedObject)));
            if (securityHandler != null) {
                securityHandler.decryptStream(stream, objKey.getNumber(), objKey.getGeneration());
            }
            parsedObject = stream;
        } else {
            // this is not legal
            // the combination of a dict and the stream/endstream
            // forms a complete stream object
            throw new IOException(("Stream not preceded by dictionary (offset: " + objOffset) + ").");
        }
        skipSpaces();
        endObjectKey = readLine();
        // we have case with a second 'endstream' before endobj
        if ((!endObjectKey.startsWith(ENDOBJ_STRING)) && endObjectKey.startsWith(ENDSTREAM_STRING)) {
            endObjectKey = endObjectKey.substring(9).trim();
            if (endObjectKey.length() == 0) {
                // no other characters in extra endstream line
                // read next line
                endObjectKey = readLine();
            }
        }
    } else if (securityHandler != null) {
        securityHandler.decrypt(parsedObject, objKey.getNumber(), objKey.getGeneration());
    }
    if (!endObjectKey.startsWith(ENDOBJ_STRING)) {
        if (isLenient) {
            LOG.warn(((((((("Object (" + readObjNr) + ":") + readObjGen) + ") at offset ") + objOffset) + " does not end with 'endobj' but with '") + endObjectKey) + "'");
        } else {
            throw new IOException(((((((("Object (" + readObjNr) + ":") + readObjGen) + ") at offset ") + objOffset) + " does not end with 'endobj' but with '") + endObjectKey) + "'");
        }
    }
    return parsedObject;
}

/**
 * This will parse a directory object from the stream.
 *
 * @return The parsed object.
 * @throws IOException
 * 		If there is an error during parsing.
 */
protected COSBase parseDirObject() throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        skipSpaces();
        char c = ((char) (source.peek()));
        switch (c) {
            case '<' :
                // pull off first left bracket
                source.read();
                // check for second left bracket
                c = ((char) (source.peek()));
                source.rewind(1);
                // PATH: Test should invoke the next BaseParser.parseCOSDictionary(...) [step in execution path]
                return c == '<' ? parseCOSDictionary(true) : parseCOSString();
            case '[' :
                // array
                return parseCOSArray();
            case '(' :
                return parseCOSString();
            case '/' :
                // name
                return parseCOSName();
            case 'n' :
                // null
                readExpectedString(NULL, false);
                return COSNull.NULL;
            case 't' :
                readExpectedString(TRUE, false);
                return COSBoolean.TRUE;
            case 'f' :
                readExpectedString(FALSE, false);
                return COSBoolean.FALSE;
            case 'R' :
                source.read();
                return new COSObject(null);
            case ((char) (-1)) :
                return null;
            default :
                if (((Character.isDigit(c) || (c == '-')) || (c == '+')) || (c == '.')) {
                    return parseCOSNumber();
                }
                // This is not suppose to happen, but we will allow for it
                // so we are more compatible with POS writers that don't
                // follow the spec
                long startOffset = source.getPosition();
                String badString = readString();
                if (badString.isEmpty()) {
                    int peek = source.peek();
                    // we can end up in an infinite loop otherwise
                    throw new IOException(((((((((((("Unknown dir object c='" + c) + "' cInt=") + ((int) (c))) + " peek='") + ((char) (peek))) + "' peekInt=") + peek) + " at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                }
                // if it's an endstream/endobj, we want to put it back so the caller will see it
                if (ENDOBJ_STRING.equals(badString) || ENDSTREAM_STRING.equals(badString)) {
                    source.rewind(badString.getBytes(StandardCharsets.ISO_8859_1).length);
                } else {
                    LOG.warn(((((("Skipped unexpected dir object = '" + badString) + "' at offset ") + source.getPosition()) + " (start offset: ") + startOffset) + ")");
                    return this instanceof PDFStreamParser ? null : COSNull.NULL;
                }
        }
        return null;
    } finally {
        recursionDepth--;
    }
}

/**
 * This will parse a PDF dictionary.
 *
 * @param isDirect
 * 		indicates whether the dictionary to be read is a direct object
 * @return The parsed dictionary, never null.
 * @throws IOException
 * 		If there is an error reading the stream.
 */
protected COSDictionary parseCOSDictionary(boolean isDirect) throws IOException {
    try {
        recursionDepth++;
        if (recursionDepth > MAX_RECURSION_DEPTH) {
            throw new IOException(MAX_RECUSRION_MSG);
        }
        readExpectedChar('<');
        readExpectedChar('<');
        skipSpaces();
        COSDictionary obj = new COSDictionary();
        obj.setDirect(isDirect);
        while (true) {
            skipSpaces();
            char c = ((char) (source.peek()));
            if (c == '>') {
                break;
            } else if (c == '/') {
                // something went wrong, most likely the dictionary is corrupted
                // stop immediately and return everything read so far
                if (!parseCOSDictionaryNameValuePair(obj)) {
                    return obj;
                }
            } else // PATH: Test should invoke the next Log.warn(...) [step in execution path]
            {
                // invalid dictionary, we were expecting a /Name, read until the end or until we can recover
                LOG.warn((("Invalid dictionary, found: '" + c) + "' but expected: '/' at offset ") + source.getPosition());
                if (readUntilEndOfCOSDictionary()) {
                    // we couldn't recover
                    return obj;
                }
            }
        } 
        try {
            readExpectedChar('>');
            readExpectedChar('>');
        } catch (IOException exception) {
            LOG.warn("Invalid dictionary, can't find end of dictionary at offset " + source.getPosition());
        }
        return obj;
    } finally {
        recursionDepth--;
    }
}

