    minX = ((int) (Math.floor(bounds.getMinX())));
    minY = ((int) (Math.floor(bounds.getMinY())));
    maxX = ((int) (Math.floor(bounds.getMaxX()))) + 1;
    maxY = ((int) (Math.floor(bounds.getMaxY()))) + 1;
