            if ((Float.compare(wordSpacing, 0) == 0) || Float.isNaN(wordSpacing)) {
                deltaSpace = Float.MAX_VALUE;
            } else if (lastWordSpacing < 0) {
                deltaSpace = wordSpacing * getSpacingTolerance();
            } else {
