/**
 * This will flatten all form fields.
 *
 * <p>
 * Flattening a form field will take the current appearance and make that part of the pages content stream. All form
 * fields and annotations associated are removed.
 * </p>
 *
 * <p>
 * Invisible and hidden fields will be skipped and will not become part of the page content stream
 * </p>
 *
 * <p>
 * The appearances for the form fields widgets will <strong>not</strong> be generated
 * </p>
 *
 * @throws IOException
 * 		if something went wrong flattening the fields
 */
public void flatten() throws IOException {
    // for dynamic XFA forms there is no flatten as this would mean to do a rendering
    // from the XFA content into a static PDF.
    if (xfaIsDynamic()) {
        LOG.warn("Flatten for a dynamix XFA form is not supported");
        return;
    }
    List<PDField> fields = new ArrayList<>();
    for (PDField field : getFieldTree()) {
        fields.add(field);
    }
    flatten(fields, false);
}

/**
 * This will flatten the specified form fields.
 *
 * <p>
 * Flattening a form field will take the current appearance and make that part of the pages content stream. All form
 * fields and annotations associated are removed.
 * </p>
 *
 * <p>
 * Invisible and hidden fields will be skipped and will not become part of the page content stream
 * </p>
 *
 * @param fields
 * 		a list of fields to be flattened
 * @param refreshAppearances
 * 		if set to true the appearances for the form field widgets will be updated
 * @throws IOException
 * 		if something went wrong flattening the fields
 */
public void flatten(List<PDField> fields, boolean refreshAppearances) throws IOException {
    // Nothing to flatten if there are no fields provided
    if (fields.isEmpty()) {
        return;
    }
    if ((!refreshAppearances) && getNeedAppearances()) {
        LOG.warn("acroForm.getNeedAppearances() returns true, " + "visual field appearances may not have been set");
        LOG.warn("call acroForm.refreshAppearances() or " + "use the flatten() method with refreshAppearances parameter");
    }
    // for dynamic XFA forms there is no flatten as this would mean to do a rendering
    // from the XFA content into a static PDF.
    if (xfaIsDynamic()) {
        LOG.warn("Flatten for a dynamix XFA form is not supported");
        return;
    }
    // refresh the appearances if set
    if (refreshAppearances) {
        refreshAppearances(fields);
    }
    PDPageTree pages = document.getPages();
    Map<COSDictionary, Set<COSDictionary>> pagesWidgetsMap = buildPagesWidgetsMap(fields, pages);
    // preserve all non widget annotations
    for (PDPage page : pages) {
        Set<COSDictionary> widgetsForPageMap = pagesWidgetsMap.get(page.getCOSObject());
        // indicates if the original content stream
        // has been wrapped in a q...Q pair.
        boolean isContentStreamWrapped = false;
        List<PDAnnotation> annotations = new ArrayList<>();
        for (PDAnnotation annotation : page.getAnnotations()) {
            if ((widgetsForPageMap == null) || (!widgetsForPageMap.contains(annotation.getCOSObject()))) {
                annotations.add(annotation);
