static PDFontDescriptor buildFontDescriptor(FontMetrics metrics) // PATH: Test should invoke the next new PDFontDescriptor(...) [step in execution path]
{
    boolean isSymbolic = metrics.getEncodingScheme().equals("FontSpecific");
    PDFontDescriptor fd = new PDFontDescriptor();
    fd.setFontName(metrics.getFontName());
    fd.setFontFamily(metrics.getFamilyName());
