        // render glyph
        Shape glyph = at.createTransformedShape(path);
        if (isContentRendered()) {
            if (renderingMode.isFill()) {
                graphics.setComposite(state.getNonStrokingJavaComposite());
                graphics.setPaint(getNonStrokingPaint());
