            switch (next) {
                case 'n' :
                    out.write('\n');
                    break;
                case 'r' :
                    out.write('\r');
                    break;
                case 't' :
                    out.write('\t');
                    break;
                case 'b' :
                    out.write('\b');
                    break;
                case 'f' :
                    out.write('\f');
                    break;
                case ')' :
